window.harnessChunks["rows-3b73f58b6548596c.js"]=["<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T03:41:21+03:00\"><th scope=\"row\"><a href=\"https://github.com/QuantaAlpha/RepoMaster\" target=\"_blank\" rel=\"noopener\">RepoMaster</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/QuantaAlpha/RepoMaster/tree/9cf59930102970d61d6eb2f702fd936d3cda7f11\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 9cf59930102970d61d6eb2f702fd936d3cda7f11\">9cf5993 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: repository/code agents autonomously explore, execute and react to task results inside their configured mode.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: scheduler→tool/agent routing and sequential fallback are delegation/orchestration. No mechanism was established for regulating interference, oscillation or shared constraints among multiple autonomous S1 units. The shallow S2=C interpretation is removed.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: the scheduler manages a current problem-solving plan but does not expose whole-system authority over persistent shared resources, capacities or multi-S1 commitments.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: result evaluation is performed by the same scheduler trajectory; no separate complementary audit channel was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: web/repository search gathers external information for the current objective, not a prospective intelligence function responsible for adapting future system strategy/capability.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: modes, prompts, tools and termination policy are developer-defined.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/2d5872972b06cc594960efefa39b785e6b88271a/assessments/repomaster.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 2d5872972b06cc594960efefa39b785e6b88271a\">2d58729 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T03:41:21+03:00\"><th scope=\"row\"><a href=\"https://github.com/earendil-works/pi\" target=\"_blank\" rel=\"noopener\">Pi</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/earendil-works/pi/tree/71dca871bc80b6bc97be37f0ca3189399d651fff\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 71dca871bc80b6bc97be37f0ca3189399d651fff\">71dca87 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: autonomous model/tool iteration is the core first-party abstraction.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: message queues and steering coordinate turns within one agent session; no mechanism was found for regulating interference among multiple autonomous S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: runtime callbacks and session controls do not create whole-system current authority over a multi-S1 organization.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: no independent/complementary audit path distinct from normal tool-loop execution was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: context preparation, compaction and model changes between turns support current execution rather than a distinct prospective environment-intelligence function.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: system prompts, tools, providers and stop/steering policy are parent/application supplied.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/2d5872972b06cc594960efefa39b785e6b88271a/assessments/pi.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 2d5872972b06cc594960efefa39b785e6b88271a\">2d58729 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T04:01:58+03:00\"><th scope=\"row\"><a href=\"https://github.com/MiroMindAI/MiroThinker\" target=\"_blank\" rel=\"noopener\">MiroThinker</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/MiroMindAI/MiroThinker/tree/1c4253f6774bf40314271a827304b842100e054c\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 1c4253f6774bf40314271a827304b842100e054c\">1c4253f &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: research agents autonomously choose search/tool actions and iterate from evidence/results.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: subagents are invoked as operational capabilities and return results to the main agent. Duplicate-query and rollback protections operate inside individual agent loops, not between autonomous S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: orchestration of current turns/subtasks does not establish whole-system regulation of shared resources, capacities or commitments.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: rollback/format checking is ordinary execution control, not a distinct complementary audit channel.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: broad external research is performed to answer the current task; post-training/trajectory refinement is not a runtime prospective intelligence function governing future organizational adaptation.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: models, prompts, tools and organizational topology remain externally configured.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c62c112b9468bc60e2a63b92623b0b69fd6248a6/assessments/mirothinker.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c62c112b9468bc60e2a63b92623b0b69fd6248a6\">c62c112 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-17T18:58:01+03:00\"><th scope=\"row\"><a href=\"https://github.com/TurixAI/TuriX-CUA\" target=\"_blank\" rel=\"noopener\">TuriX-CUA</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-17\">2026-10-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/TurixAI/TuriX-CUA/tree/88c777bddfec9796667445873886a3563aa27246\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 88c777bddfec9796667445873886a3563aa27246\">88c777b &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: First-party model-directed GUI task execution with observation/action/result feedback. - Disturbance / variety regulated: Changing macOS screens, UI element locations, login prompts, incomplete subtasks, unexpected app responses and errors. - Decisive decision or feedback right: Brain LLM interprets screenshots and chooses a current procedural goal; Actor LLM chooses corresponding GUI actions and arguments; first-party agent loop decides when to continue/stop on current outcome. - Decision owner: One first-party Agent system implementing model-driven Brain/Actor decision turns; inference providers supply models, not an additional prebuilt external computer-use harness. - Supporting / enforcement mechanisms: MacUITreeBuilder screenshot/accessibility capture, Controller action registry, structured output parser, task history, action results, failure/step limits, optional Planner/skills/search/memory. - Closure path: GUI screenshot/previous action → Brain nextgoal and analysis → Actor action JSON → installed Controller.multiact executes on macOS → next screenshot/action history → Brain reevaluates and selects next goal. - Boundary reachability: examples/main.py instantiates shipped Agent with supplied Brain/Actor/Memory and optional Planner models, and calls Agent.run(maxsteps); run loops brainstep and actorstep, which invokes first-party Controller.multiact. No separate tool-providing external agent is required for this code path. - Why this is / is not agent-owned: Models make concrete runtime choice of next goal and GUI actions; execution is not limited to static hard-coded macros. The orchestrator/Controller still enforce data/step/action bounds. - Evidence: examples/main.py; src/agent/service.py; src/agent/views.py; src/controller/service.py; src/mac/actions.py. - Basis: Source-level reachable model GUI observation/feedback loop. - Confidence: High for source reachability; no external macOS/live-model execution attempted. - Caveats: Requires macOS native frameworks and a working configured provider; real task performance not established.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No first-party mutual attenuation of interference among distinct independently operating S1 units proven. - Disturbance / variety regulated: A model Brain/Actor disagreement concerns one task&#39;s sequence and action quality, not a documented conflict among separate concurrent S1 units. - Decisive decision or feedback right: No coordinator detecting and attenuating actual contention across separate worker tasks, desktop agents or resource reservations. - Decision owner: One Agent&#39;s sequential execution scheduler, which passes single-task state between subroles. - Supporting / enforcement mechanisms: Structured role outputs, action list, one-step loop, last-step history, optional plan and memory. - Closure path: Result flows between Brain and Actor for the same task; no separate inter-S1 disturbance → coordination choice → changed sibling activity feedback path evidenced. - Why this is / is not agent-owned: Brain, Actor, Memory and Planner are model calls in a single operation. Distinct LLM configurations do not create distinct organizational S1 operations. - Evidence: src/agent/service.py; src/agent/plannerservice.py; src/agent/messagemanager/service.py; examples/main.py. - Basis: Bounded negative structural search at frozen default distribution. - Confidence: Medium-high. - Caveats: An external multi-agent system may run multiple instances but its coordination is not supplied by this pinned core.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No separately owned current whole-system commitments/resources regulation beyond the one task&#39;s own planner/controller. - Disturbance / variety regulated: Current GUI subgoal failure, incomplete plan steps, retries and model output errors within one operational task. - Decisive decision or feedback right: Brain chooses current next goal and optional Planner composes current user&#39;s task; no actor chooses among organization-wide competing active tasks, priorities, resources or responsibilities. - Decision owner: One task-level Brain/Actor agent; user supplies task, and deterministic loop enforces max steps/failure cap. - Supporting / enforcement mechanisms: Current screenshot evaluation, Planner plan generation, pause/stop controls, max failures/steps. - Closure path: Next goal → individual task action → next task observation, not separate whole-operational control → reallocation/return across concurrent operational units. - Why this is / is not agent-owned: Brain is a task planner/evaluator, not whole-system S3 despite &#39;planner&#39; labels, and the task&#39;s bounded loop is not a delegated operational-management position. - Evidence: src/agent/service.py; src/agent/plannerservice.py; examples/config.json. - Basis: Bounded negative review of decisive assignment and resource authority. - Confidence: Medium-high within declared single-run operational recursion. - Caveats: Additional multi-agent orchestration in an external OpenClaw runtime is not credited to TuriX-CUA.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No independent complementary access/challenge of operational claims plus corrective return separate from ordinary execution was evidenced. - Disturbance / variety regulated: Action success/failure and changed UI state are ordinary primary task feedback. - Decisive decision or feedback right: The same Brain that determines next task decisions also judges previous-step screenshot success; Controller returns local action results, not an independently owned auditor verdict. - Decision owner: Within-task Brain/model and deterministic controller/result parser. - Supporting / enforcement mechanisms: Screenshot comparisons, stepevaluate, saved action histories, action errors and in-task memory summaries. - Closure path: Actor executes → Brain sees next screenshot and self-checks → Brain picks task continuation. This is first-party S1 feedback, not an alternative independent auditor collecting separately scoped operational evidence. - Why this is / is not agent-owned: Prompt-separated Brain versus Actor gives functional division but same run/controller authority. A different model role alone is not enough to demonstrate independent audit rights. - Evidence: src/agent/service.py; src/agent/prompts.py; src/agent/views.py; src/controller/service.py. - Basis: Bounded negative ownership/independence comparison. - Confidence: Medium-high. - Caveats: A user can manually inspect a GUI, but no shipped agent-independent audit return is evidenced.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No supported external prospective change-of-organizational-capability option and return loop. - Disturbance / variety regulated: Unseen webpage changes and task uncertainty are current operational disturbances; model/GUI capabilities are specified through configured endpoints/skills. - Decisive decision or feedback right: Optional Planner may search or choose a skill for the present user task; Memory compresses/retrieves prior action context. Neither chooses/testing a new future capability for the harness and returns it to subsequent operation. - Decision owner: Task-driven model roles and operator-managed code/skill/model settings. - Supporting / enforcement mechanisms: PlannerSearch and skill selection, Memory LLM summaries, record persistence and resumed action history. - Closure path: Search/record → better present task steps; no current-capability evidence → prospective alternatives → adaptation selection/application → later organizational operation closure. - Why this is / is not agent-owned: Learning a webpage or summarizing an execution trace is not future adaptation of the computer-use organization&#39;s capability. - Evidence: src/agent/plannerservice.py; src/agent/service.py; src/utils/skills.py; src/utils/recordstore.py. - Basis: Bounded review of optional planning/search/memory and configured skills. - Confidence: Medium-high. - Caveats: The operator could install new skills manually outside the runtime; not evidence of an installed S4.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No ultimate identity/policy decision rights or returned resolution for the computer-use system. - Disturbance / variety regulated: Human login/preferences, step-stop limits, model instructions and selected provider/tool capabilities are task-level constraints. - Decisive decision or feedback right: Operator chooses starting task and may cancel; Brain askhuman asks for clarification. No supported actor decides system-wide ultimate ethos/identity conflict and returns binding policy. - Decision owner: Human task originator and externally maintained software settings; no function-specific S5 owner evidenced in the shipped harness. - Supporting / enforcement mechanisms: User task prompt, askhuman, pause/stop and force-stop hotkey, configured model API and skills. - Closure path: User clarifies an input or cancels a task; there is no independent policy controversy → ultimate authority decision → policy return to organization. - Why this is / is not agent-owned: Static prompts/user approval do not equal agent-owned or parent-governed S5 under the active Methodology. - Evidence: src/agent/views.py; src/agent/service.py; examples/main.py; examples/config.json. - Basis: Bounded negative source review of human and task authority. - Confidence: Medium-high. - Caveats: A deploying organization may have its own user approval policy, outside the credited system.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/093016a38ca74a0929f3e6eb9d6ac5a7a62fa831/assessments/turix-cua.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 093016a38ca74a0929f3e6eb9d6ac5a7a62fa831\">093016a &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-10-23T17:11:34+03:00\"><th scope=\"row\"><a href=\"https://github.com/Nano-Collective/nanocoder\" target=\"_blank\" rel=\"noopener\">Nanocoder</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-23\">2026-10-23</time></td><td class=\"review-ref\"><a href=\"https://github.com/Nano-Collective/nanocoder/tree/258a916ee5bff51564635100a71625b63fb99673\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 258a916ee5bff51564635100a71625b63fb99673\">258a916 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: turn a natural-language or subscribed skill task into repository inspection, model-selected tool actions and a reported outcome. - Disturbance / variety regulated: changing repository contents, unfamiliar files, tool failures, user objectives, provider responses and triggered skill inputs. - Decisive decision or feedback right: the main agent or a delegated/triggered subagent selects next actions after model/tool feedback. - Decision owner: the first-party model-backed main or subagent instance; the daemon&#39;s event matcher merely schedules the latter. - Supporting / enforcement mechanisms: tool registry, context/message store, permission resolver, mode-specific tool filtering, prompt builder, configurable model providers and per-project daemon. - Closure path: prompt or event → agent model/tool choice → tool execution and result → agent model&#39;s next choice or final outcome. - Boundary reachability: the supported terminal/headless runner and agent tool construct the shipped executors; the optional daemon wires subscription dispatch into a real subagent executor. - Why this is / is not agent-owned: the agent selects operations based on changing feedback, unlike the fixed event router or tool executor. - Evidence: conversation-loop.tsx, agent-tool.tsx, subagent-executor.ts. - Basis: source-verified, with first-party fake-provider/script tests; no live LLM-agent performance run. - Confidence: high for the shipped execution path, not measured task quality. - Caveats: no default guarantee that a particular optional skill or subagent is configured, and subscribed runs require the daemon to be running.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate destructive overlap and event storms among separate model-backed runs of one daemon subscription. - Disturbance / variety regulated: a burst of file changes or another cron/file event can start multiple concurrent project-mutating agents for the same skill before a previous run completes. - Distinct S1 units: potential overlapping SubagentExecutor run instances from one registered agent:/command: subscription; each is a separately deciding model agent, not a mere tool call. - Inter-S1 disturbance: duplicate concurrent executions of one skill could race over the same work surface and overload local resources. - Decisive decision or feedback right: fixed first-party per-subscription admission/suppression of overlapping triggered runs, not the model&#39;s choice of downstream task work. - Attenuating coordination relation: the subscription ID identifies the shared project task cell; a deterministic in-flight exclusion gate prevents two such independently deciding cells from running at the same time, and the file watcher coalesces repeated changes. - Feedback into subsequent S1 behaviour: permitted event delivery starts the model worker; suppressed concurrent events do not start competing workers, while subsequent eligible events can again launch one after the previous run exits. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the code enforces an exclusion precisely against duplicate concurrently mutating agent runs for the same subscription, not merely moving messages or assigning children; unlike a global mutex it is narrowly scoped to this inter-run disturbance. - Coordination channel and decisive right: BackpressureDispatcher checks a subscription-specific in-flight set and deterministically drops a new event if a run with that ID is active; file changes are trailing-edge debounced. - Decision owner: first-party deterministic runtime C, not the triggered agent or an autonomous S2 manager. - Supporting / enforcement mechanisms: EventRouter registered subscription identity, BackpressureDispatcher in-flight set/debouncer and SkillDispatcher model-backed execution. - Closure path: matching event → per-subscription gate → at most one in-flight model run for that subscription; excess events are dropped and later eligible events can execute. - Boundary reachability: the startDaemon production path constructs the router → backpressure wrapper → skill dispatcher → model-backed executor and starts actual filesystem/cron event sources when the operator enables daemon mode. - Boundary reachability: startDaemon wraps the actual skill dispatcher with BackpressureDispatcher before subscribing file watcher/cron sources; script test explicitly checks drop-while-in-flight. - Why this is / is not agent-owned: protective inter-run scheduling is fixed source logic; the agents do not choose or negotiate interference responses. - Evidence: daemon.ts, backpressure.ts, backpressure.spec.ts. - Basis: explicit code wiring and deterministic first-party script test. - Confidence: medium-high for the bounded daemon overlap case, low for general multi-agent collaboration. - Caveats: not a global project lock; different subscriptions or ordinary parallel agent calls may still edit the same files concurrently. Excess triggers are dropped, not durably queued or reconciled.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no demonstrated whole-current operational management with selectable priorities/resources and an intervention return across the assessed agent cohort. - Disturbance / variety regulated: competing active commitments, slow/stuck workers or cross-subscription project resource conflicts could need higher-level decisions. - Decisive decision or feedback right: the main model can delegate tasks and consume each worker&#39;s final result; a human can choose the overall mode or interrupt a turn; the daemon enforces a fixed per-subscription cap. No model/operator current-work portfolio decision with a sufficiently specific management return is demonstrated. - Decision owner: none established for whole-cohort S3; model and human retain local task/delegation/permission rights. - Supporting / enforcement mechanisms: parallel subagent progress map and UI, depth/fan-out limits, abort signal, mode resolver, task list, daemon per-subscription gate and event logging. - Closure path: subagent final result → originating parent&#39;s ordinary next task decision, or top-level cancel; no current cohort inspection → selective commitment/resource intervention → workers&#39; ongoing changed operations path was evidenced. - Why this is / is not agent-owned: delegation, UI progress and bounded concurrency alone do not prove autonomous or parent-governed S3 resource management. - Evidence: tool-executor.tsx, subagent-events.ts, subagent-executor.ts. - Basis: structural source inspection and bounded absence review. - Confidence: medium. - Caveats: external organizations could wrap Nanocoder with higher-level governance, which is not first-party S3 in this local product boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no independently accessed check of S1 operational claims with a finding fed to a responsible S3 controller was established. - Disturbance / variety regulated: false claims of work completion and uncontrolled code changes may occur, but routine tool outputs or test execution are not separate audit ownership. - Decisive decision or feedback right: the producer model can run tests or use hooks; a user may review actions, and custom reviewer agents may be authored, but no independent first-party complementary audit is mandated/wired with corrective closure. - Decision owner: none established for an S3 audit function. - Supporting / enforcement mechanisms: tool hooks, verification helpers, checkpoints, code diagnostics, subagent isolation, logs and first-party AVA tests. - Closure path: ordinary tool and hook results → same acting agent or user approval; no complementary audit claim → S3 corrective return is wired. - Why this is / is not agent-owned: optional user-defined reviewers and adjacent tests cannot be counted as first-party production audit merely because they can inspect code. - Evidence: subagent-executor.ts, approval-policy.ts, subagents.md. - Basis: explicit design and bounded absence review. - Confidence: medium-high. - Caveats: a downstream team can construct a genuine independent review skill, but an available construction capability is not a demonstrated shipped audit circuit.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no closed future-facing external-environment option development and return to harness capability was identified. - Disturbance / variety regulated: changing model capabilities, users, ecosystem constraints and future task demands would require strategic adaptation, whereas file/cron events are present-state triggers. - Decisive decision or feedback right: the working model may consult external tools, maintain memory or revise a task plan; a configured skill may react to file changes. None is demonstrated as first-party prospective adaptation governance. - Decision owner: current S1 task agent for immediate choices and external human/maintainers for later product or skill redesign. - Supporting / enforcement mechanisms: semantic memory, web/MCP tools, plan/architect modes, skill manifests, cron/file subscriptions and checkpoints. - Closure path: current observations → local task response, or event → registered task run; no future environmental model → adaptation options → capability-update/control dialogue path is evidenced. - Why this is / is not agent-owned: reactive subscriptions and a generic skill constructor do not themselves create S4; no default research-to-redesign loop is shipped. - Evidence: skills.md, dispatcher.ts, daemon.ts. - Basis: bounded first-party path review. - Confidence: medium. - Caveats: external users could implement a prospective watcher, but that is a configured use case, not credited as default harness S4.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no in-boundary ultimate-identity/policy decision and authoritative closure is evidenced. - Disturbance / variety regulated: risky command execution and permitted tools are constrained locally; higher-level conflicts over organizational ethos or future-versus-present policy remain external. - Decisive decision or feedback right: the user selects modes, preauthorizes tools or answers operational prompts; skill authors configure permissions. This is not an identity-level adjudication with S3–S4 return. - Decision owner: no first-party legitimate S5 actor or closed parent arrangement established within the operating product. - Supporting / enforcement mechanisms: resolveToolApproval, alwaysAllow, mode-sensitive tool availability, blocked subagent tools and headless/plan constraints. - Closure path: per-tool approval/mode configuration governs individual operations; no policy-identity proposal → legitimate ultimate authority → system-wide decision return path is evidenced. - Why this is / is not agent-owned: static developer rules and granular user consent are action permission, not VSM S5 decision rights. - Evidence: approval-policy.ts, development-modes.md, subagent-executor.ts. - Basis: explicit first-party permission mechanisms and bounded absence review. - Confidence: medium-high. - Caveats: a separately governed organization can set an identity for deployments; this assessment does not equate the product&#39;s maintainers with a live S5 parent.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/57ad4643834168eed26c27056e2d4e04cdc0ce4b/assessments/na/nanocoder.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 57ad4643834168eed26c27056e2d4e04cdc0ce4b\">57ad464 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-18T00:14:55+03:00\"><th scope=\"row\"><a href=\"https://github.com/openonion/connectonion\" target=\"_blank\" rel=\"noopener\">ConnectOnion</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-18\">2026-10-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/openonion/connectonion/tree/7011faa911e2563e485f865db5be60f6e595f1bd\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 7011faa911e2563e485f865db5be60f6e595f1bd\">7011faa &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: Perform user-specified work by model-directed choice of first-party registered tools/subagents and respond using returned execution observations. - Disturbance / variety regulated: Changing freeform user requests, tool failures/outputs, subagent responses, environment state, interruptions and context changes during the turn. - Decisive decision or feedback right: Agent model chooses next tool call or final response given accumulated messages/tool observations; a delegated subagent makes local model decisions within its allowed tools. - Decision owner: Configured model-backed Agent/concrete co ai first-party execution loop; provider infrastructure is a dependency, not an imported organizational actor. - Supporting / enforcement mechanisms: LLM adapters, ToolRegistry and tool executor, conversation/trace, explicit operator approvals, TodoList, optional subagent and skill registration, iteration bounds and stop gates. - Closure path: User/input or hosted inbound prompt → Agent.input → runiterationloop → getllmdecision → first-party tool executor or delegated task → captured toolresult/error in messages/trace → next model decision/answer or bounded stop. - Boundary reachability: The exported Agent.input directly calls the real run loop; default createagent registers first-party plugins and tools on that concrete Agent, not only a sample. Subagent tool explicitly instantiates and executes a real local Agent. - Why this is / is not agent-owned: Model-selected tool/response decisions condition on live observations; executor, provider transport, static permissions and scheduled entry do not substitute for the agent&#39;s choices. - Evidence: agent.py; agent.py; agent.py; toolexecutor.py; subagents.py; agent.py. - Basis: Explicit first-party runtime source and actual tool/result return. - Confidence: High for shipped code structure/reachability; no live provider workload benchmark in this review. - Caveats: Requires configured provider, runnable tools and permissions; subagents/remote coding CLIs are not evidence of autonomous other VSM functions.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No proven first-party S2-specific attenuation of concrete clashes among distinct viable S1 operational participants at assessed recursion. - Disturbance / variety regulated: Potential conflicting tool writes, duplicate requests and simultaneous subordinate work; the reviewed mechanisms bound a tool session and admission rather than negotiate interference among independent cells. - Decisive decision or feedback right: Parent model chooses when to invoke task or other tools; deterministic host approval/permission rules enforce per-request safety. - Decision owner: Task-local caller/model and mechanical permission/host mechanisms, with no evidenced distinct inter-unit adjustment owner. - Supporting / enforcement mechanisms: Per-call sequential tool execution, subagent task API, session serialization/host state, tool approval and provider workroom state. - Closure path: Delegated subagent sends result back to caller; no demonstrated disturbance between two independent S1 units → conflict-sensitive coordination choice → returned stabilizing changes to their later operations. - Why this is / is not agent-owned: Subagent dispatch and same-turn tool ordering are composition/scheduling, not a distinct operational S2 conflict attenuation loop. - Evidence: subagents.py; toolexecutor.py; providerworkroom.py; approval.py. - Basis: Reviewed installed delegation and execution coordination surfaces; bounded negative. - Confidence: Medium-high at defined distributed app boundary. - Caveats: Custom adopters can build their own cross-agent coordinator; that is not shown as an included native S2 operating mode.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No established whole-current aggregate control loop across independently executing Agent operations. - Disturbance / variety regulated: Task backlogs, concurrent hosted sessions, scheduled work, tool costs and competing commitments that could require system-level current prioritization. - Decisive decision or feedback right: Individual task model sets steps/tools; host scheduler executes author-specified entries; approval hook enforces permissions. No app-scoped present-wide resource/commitment decision-right shown. - Decision owner: Per-agent model, deterministic hosted scheduler and external operator setting static job rules; no demonstrated S3 owner or parent S3 adjudication/return cycle. - Supporting / enforcement mechanisms: TodoList, per-agent max iterations, stop handling, workroom run/trace, schedule-state and status views, host deployment. - Closure path: Per-task execution and scheduling have operational completion receipts, but no whole-current work-state integration → binding cross-S1 prioritization/commitment negotiation → changed subsequent agent operations. - Why this is / is not agent-owned: An autonomous per-task plan is not S3 at this recursion, nor does a cron dispatcher become an organizational current-control decision-maker. - Evidence: agent.py; schedule.py; todolist.py; providerworkroom.py; agent.py. - Basis: Source-inspected runtime, scheduling and host responsibilities; bounded negative. - Confidence: Medium-high for default/packaged modes. - Caveats: External owner may use manual controls for their larger organization; not credited as a ConnectOnion-shipped parent return path.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: Complementary independent challenge of ordinary operating reality returning into current control was not established. - Disturbance / variety regulated: Agent&#39;s potentially misleading self-report of completed work and inaccurate tool outcomes; optional eval can score such reports but is not wired into current control. - Decisive decision or feedback right: Optional eval computes post-turn expected vs observed summary and LLM pass/fail; writes an evaluation UI/trace event, with no evidenced independent authority to challenge an S3 claim and force current operational correction. - Decision owner: Extra optional scorer model plus caller choosing plugin, separated from required first-party operating control; it is not demonstrated an S3 operating auditor. - Supporting / enforcement mechanisms: Turn trace, summarization, oncomplete handler, expected-outcome prompt, UI eval event; debug/auto-debug instrumentation. - Closure path: Agent turn completes → optional post-turn judge reads requested intent/actions/response → records and displays evaluation. Missing return: independent finding → accountable whole-current S3 reconsideration/withholding/corrective decision → changed S1 operation. - Why this is / is not agent-owned: A model grading completed task quality is genuine evaluation but its stored output is not a complementary governance audit with closed corrective challenge of current-control reporting. - Evidence: eval.py; eval.py; eval.py; agent.py; agent.py. - Basis: Explicit optional eval handler, separate post-task output and default factory plugin list inspection. - Confidence: Medium-high in evaluated native paths. - Caveats: Adopters can read UI evaluation and choose manual corrective interventions externally; this is not an evidenced built-in S3 return path.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S4 / adaptation: - State: ? - Function: Plausible first-party prospective capability creation via model-selected skill authoring, but an accountable future-adaptation decision plus return into subsequently installed operation is not established. - Disturbance / variety regulated: New automation sites, changed external interfaces, recurring tool workflows and a need for durable reusable future capabilities beyond the current task. - Decisive decision or feedback right: The shipped model-backed co ai can write files and invoke skills; packaged browser-workflow-skill-builder instructs a user/agent to create a new SKILL.md under project skills and test helper scripts. Who accepts/promotes a candidate as a system future strategy/capability and when it becomes active is not fully established. - Decision owner: Model-assisted skill authoring under user tool permissions; first-party skills loader discovers/loads available skills. The prospective parent/operator selection and systematic future-control authority remain unresolved. - Supporting / enforcement mechanisms: File tools, developer-selected skills, skill invocation, project skill discovery, runtime prompt instructions and tool approval. - Closure path: Novel task/site issue → optionally invoke supplied skill-builder recipe → model/file tools create or edit a project skill → loader may discover and invoke this artifact on a later task. Missing: evidenced S4-specific option comparison/selection by legitimate future intelligence owner and a returned institutional decision admitting a new capability to future operation. - Why this is / is not agent-owned: Writing durable skill code under a prompted task may be ordinary S1 programming work; a usable skills loader alone is not proof that the agent exercises a distinct S4 future/environment adaptation right. Material shipped candidate precludes an unqualified absence conclusion. - Evidence: agent.py; skills.py; skills.py; skills.py; SKILL.md; SKILL.md; agent.py. - Basis: Specific shipped skills authoring, file I/O and future load path, but missing conclusive S4 decision/return reconstruction. - Confidence: High for authoring/availability mechanics; low for whole S4 ownership state. - Caveats: Need a source-verified or controlled reproduction tying the model&#39;s prospective selection, durable skill admission and later changed operating options to one first-party S4 function, separated from ordinary user-requested coding.\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No first-party legitimate ultimate-purpose/organizational-identity decision and returned policy closure established, despite trust and tool authorization. - Disturbance / variety regulated: Untrusted remote clients, tool risk, provider delegation and access-right changes; these are operational admission/safety disturbances, not by themselves ultimate identity disputes. - Decisive decision or feedback right: TrustAgent applies configured allow/deny rules and optionally a model &#39;ask&#39; for unknown remote clients; owner/operator approves tool execution. Nothing in these paths defines and adjudicates the installed agent&#39;s ultimate purpose or ethos on behalf of its governed organization. - Decision owner: Operator-configured trust/permission policies, per-request user, deterministic gate and bounded trust model decision for admission; not an established S5 organizational parent. - Supporting / enforcement mechanisms: Signed client identity/trust levels, trusted-client onboarding, tool approval modes, permission scopes and audit/trace. - Closure path: Client request → trust allow/deny, or tool action → permission/approval → execution/blocked outcome; no distinct ultimate identity/purpose dispute → legitimate parent decision → accepted revised governing policy affecting later operations was established. - Why this is / is not agent-owned: An autonomous classifier of access to an endpoint is not the final legitimate guardian of an organization&#39;s identity; self-hosted owner may provide that authority externally. - Evidence: trustagent.py; trustagent.py; approval.py; skills.py; agent.py. - Basis: Explicit first-party trust and permissions control plus boundary-relative negative adjudication. - Confidence: Medium-high for selected packaged modes. - Caveats: Self-hosted operators retain ultimate external governance of what this agent is for; no first-party parent-mode closure is claimed.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/08bcb42e2953ad3304dc3b6275958bf2480c96ad/assessments/connectonion.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 08bcb42e2953ad3304dc3b6275958bf2480c96ad\">08bcb42 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-05T18:43:41+03:00\"><th scope=\"row\"><a href=\"https://github.com/ovh/shai\" target=\"_blank\" rel=\"noopener\">SHAI</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-05\">2026-10-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/ovh/shai/tree/f076f6128a826a96a28e47d0d674284b1552905e\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision f076f6128a826a96a28e47d0d674284b1552905e\">f076f61 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: autonomously perform coding work by selecting and revising model/tool actions against the live project environment. - Disturbance / variety regulated: unfamiliar codebases, changing file state, command failures, incomplete context, model/tool errors, permission requirements and user corrections. - Decisive decision or feedback right: choose the next reasoning/tool action, interpret returned evidence, continue or pause, and revise subsequent work until the coding request is complete or terminated. - Decision owner: the active model-backed SHAI Brain. - Supporting / enforcement mechanisms: agent state machine, coder prompt/runner, filesystem/shell/fetch/todo/MCP tools, claim manager, controller protocol, project-context loading and provider adapters. - Closure path: user/project context → model chooses action/tool → tool or environment returns evidence → evidence is appended to the trace → model chooses the next action until terminal completion, pause or cancellation. - Boundary reachability: interactive CLI, headless mode and HTTP sessions all instantiate the repository-owned agent core/coder runner directly; no adjacent development workflow is required. - Why this is / is not agent-owned: removing the model actor leaves the state machine, tools and controller but removes the open-ended coding decisions that turn observations into subsequent actions. - Evidence: README; shai-core/src/agent/README.md; shai-core/src/agent/agent.rs; shai-core/src/agent/brain.rs; shai-core/src/runners/coder/coder.rs; built-in tool implementations. - Basis: explicit + structural. - Confidence: high. - Caveats: external providers supply inference and MCP services may add tools, but their internal behavior is not credited to SHAI.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no distinct inter-S1 coordination function is established. - Disturbance / variety regulated: concurrent tool calls and multiple HTTP sessions exist, but they are not evidenced as distinct S1 units whose mutual interference is regulated through a coordination loop. - Decisive decision or feedback right: no S2-specific decision over a concrete inter-S1 conflict or oscillation was found. - Decision owner: not established at S2 level. - Supporting / enforcement mechanisms: async tool aggregation, per-session controller locking, session IDs and request serialization. - Closure path: these mechanisms serialize or isolate work inside individual sessions; they do not close a peer coordination relation among distinct operational units. - Why this is / is not agent-owned: concurrency and session isolation are implementation mechanisms, not evidence of S2 by themselves. - Evidence: agent architecture README; shai-core/src/agent/agent.rs; shai-http/src/session/session.rs; shai-http/src/session/manager.rs. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: separately launched SHAI agents could be composed externally, but no first-party coordination relation among them is supplied in the frozen standard distribution.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct whole-system current-control function is established. - Disturbance / variety regulated: session cancellation, permission handling and a configured maximum session count constrain current execution, but they do not provide substantive whole-system resource/commitment management. - Decisive decision or feedback right: no separate actor observes the whole set of current operations and makes discretionary choices over shared priorities, resources, commitments or interventions on behalf of the whole. - Decision owner: not established at S3 level. - Supporting / enforcement mechanisms: HTTP session map, static maxsessions limit, per-session controller lock, cancel/state protocol and permission handling. - Closure path: the session manager deterministically accepts a new session when below a configured count and rejects it when full; session-local controller actions affect only the focal agent. - Why this is / is not agent-owned: the hard concurrency cap enforces a configured limit but does not supply the whole-current decision authority required for S3. - Evidence: shai-http/src/session/manager.rs; shai-http/src/session/session.rs; shai-core/src/agent/protocol.rs; shai-core/src/agent/claims.rs. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: an external service operator may choose configuration and terminate sessions, but generic operational administration is not a first-party S3 closure at this boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no complementary audit path distinct from ordinary production feedback is established. - Disturbance / variety regulated: shell output, tool results, traces and repository tests can reveal mistakes, but the same coding agent consumes these as ordinary operational evidence. - Decisive decision or feedback right: no separate auditor owns an independent claim-checking judgment that returns findings into current control. - Decision owner: not established at S3 level. - Supporting / enforcement mechanisms: tool result events, trace logging, shell/build execution, repository tests and HTTP event streams. - Closure path: execution evidence returns directly into the same agent trace or external client; no separate complementary-access audit loop is supplied. - Why this is / is not agent-owned: routine self-checking and observability do not establish S3. - Evidence: shai-core/src/agent/events.rs; built-in tools; agent output/logging; repository tests; HTTP event logging. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: users may independently inspect results, but no first-party reviewer/evaluator runtime closes that path.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no externally and prospectively oriented adaptation loop is established. - Disturbance / variety regulated: persistent traces, project SHAI.md, custom agent configs, provider selection and MCP configuration can influence later sessions. - Decisive decision or feedback right: no first-party process senses future/external change, develops adaptation options for SHAI and returns a selected option into current organizational capability. - Decision owner: not established at S4 level. - Supporting / enforcement mechanisms: session persistence, project context files, custom-agent configuration, provider/model selection and MCP configuration. - Closure path: stored traces/configuration are replayed or loaded into later operational runs; they do not form an external-and-prospective adaptation conversation. - Why this is / is not agent-owned: persistence and extensibility change context/capabilities only when supplied by users/configuration and do not autonomously generate future-oriented adaptation options. - Evidence: README; SHAI.md; shai-http/src/session/persist.rs; shai-core/src/config/agent.rs; MCP configuration. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: external operators can create new agent configurations, but generic configurability is not S4.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no identity- or ultimate-policy-level closure is established. - Disturbance / variety regulated: tool claims, sudo mode, permission requests, agent configuration and external controller commands constrain ordinary task execution. - Decisive decision or feedback right: no identity/ultimate-policy issue is routed to legitimate ultimate authority and returned as a durable governing decision for SHAI. - Decision owner: not established at S5 level. - Supporting / enforcement mechanisms: ClaimManager, sudo/no-sudo mode, permission protocol, custom-agent config and user/project context. - Closure path: permissions and controller commands allow or deny current actions, but do not settle identity-level policy questions for subsequent system operation. - Why this is / is not agent-owned: guardrails and ordinary approval are execution constraints, not S5. - Evidence: shai-core/src/agent/claims.rs; shai-core/src/agent/agent.rs; protocol/configuration surfaces. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: maintainers and service operators have governance authority outside the focal runtime, but that adjacent authority is not an operational S5 loop.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/08e55e86d5171d1f261ba0ecba7dd97b9e65b5be/assessments/shai.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 08e55e86d5171d1f261ba0ecba7dd97b9e65b5be\">08e55e8 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-25T01:19:32+03:00\"><th scope=\"row\"><a href=\"https://github.com/bubbuild/bub\" target=\"_blank\" rel=\"noopener\">Bub</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-25\">2026-10-25</time></td><td class=\"review-ref\"><a href=\"https://github.com/bubbuild/bub/tree/71d7dbf82f9e7145aabf53ab562c1d376bb3e0e2\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 71d7dbf82f9e7145aabf53ab562c1d376bb3e0e2\">71d7dbf &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: Autonomously complete assigned tasks via model-selected tool actions and feedback-informed next model steps. - Disturbance / variety regulated: User goals, tool-return data, execution errors, changing session messages and provider responses require task-specific action selection. - Decisive decision or feedback right: The model chooses content and offered tool invocations; the first-party agent executes chosen calls and exposes the results to subsequent model decisions. - Decision owner: Configured model-backed Agent/BubAgent work cell; the external inference service supplies decisions through a deliberately integrated provider interface. - Supporting / enforcement mechanisms: Tape/history, tool call executor, bounded model steps, events, per-session state, skills, configured permissions and optional subtask call. - Closure path: BubAgent.runstream → Agent.start/runsteps → runonce/model streaming → model-selected tool call → ToolExecutor and tool result → recorded tape/model context → next step or final output. - Boundary reachability: BubAgent and core Agent are concrete installable first-party runtime classes; normal configured operation reaches this loop without an application-defined replacement agent. - Why this is / is not agent-owned: The tool executor, session handler and fixed step caps cannot themselves select a semantic next action from task/observation content. The configured model-backed work cell does. - Evidence: implemented step loop; model streaming; configured turn; first-party subtask. - Basis: Structural source inspection of the first-party model/tool/result feedback loop and published standard runtime. - Confidence: High for implemented decision loop; no live-model efficacy/safety claim. - Caveats: Requires a configured model and runtime tools. A standalone subtask is not automatically a separately viable management layer.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No shipped conflict-specific regulator is evidenced that detects and attenuates disturbances between two independently operating S1 units. - Disturbance / variety regulated: Two sessions/subtasks may compete for shared tools, write to common resources or generate inconsistent proposals; first-party path does not detect or settle such cross-agent interference. - Distinct S1 units: Separate configured BubAgent instances or task runs can host model-backed loops; the subagent tool uses the parent&#39;s own runtime, only changing the session/tool scope. - Inter-S1 disturbance: No concrete peer-conflict signal, oscillation detector, ownership collision or resource contention reconciliation is found in the shipped subagent/admission path. - Attenuating coordination relation: Channel admission affects new messages and session activity; subagent delegation waits for an output; tool executor gathers concurrent calls without a shared-work conflict policy. - Feedback into subsequent S1 behaviour: Model can read delegated text/error results as ordinary work input, but no inter-S1 conflict outcome is fed back under a dedicated coordination decision. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: Message admission and worker handoff are mechanisms that a larger S2 might use, not proof of a particular collision or disagreement and its mitigation. Explicit first-party default concurrency test confirms admission is not a universal serializing inter-agent guard. - Decisive decision or feedback right: User/plugin provides optional admission policy; first-party code applies AdmitDecision, not an inter-agent reconciliation rule. - Decision owner: No qualified S2 owner in the reviewed first-party boundary. - Supporting / enforcement mechanisms: Session pending queue, steering inbox, quit cancellation, model tool allowlist, optional tool concurrency limiter, subagent prompt/result. - Closure path: Incoming session message → optional admission decision → process/drop/queue/steer; parent subtask call → child output. Neither closes detected inter-S1 interference into revised multiple-agent work. - Why this is / is not agent-owned: Model-originated delegation can be autonomous S1 task decomposition, but the admission actions are externally provided or single-session controls, not an agent-owned cross-S1 stabilization function. - Evidence: subagent call and result; admission decision actions; concurrent tool calls; default concurrent turns test. - Basis: Bounded negative on first-party multi-run and channel interfaces. - Confidence: Medium-high. - Caveats: A consumer-supplied admission hook could build an inter-agent policy; absent concrete shipped ownership, it is not credited to Bub.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No first-party manager appraises the current whole of active operational units and revises their shared task commitments, resource allocations or priorities. - Disturbance / variety regulated: Concurrent sessions and subtask work could consume capacity or drift from higher-level objectives, but the standard controls manage one run or a fixed session queue. - Decisive decision or feedback right: The operator supplies tasks/permissions/models and may interrupt a session; a model can choose to call a child for its own task but cannot, through the shipped subagent tool, inspect/rebalance an active agent organization. - Decision owner: Caller/developer for population topology and process settings; one operational parent model for task delegation, not an established separate whole-current manager. - Supporting / enforcement mechanisms: ChannelManager.activetasks, turn snapshots, quit, tool budgets/maxsteps, parent/child session IDs and optional hooks. - Closure path: One parent awaits subtask output; individual sessions can be interrupted or queued. No whole-current appraisal → commitment/resource choice → changed operating-unit priorities exists. - Why this is / is not agent-owned: The model chooses whether to decompose its present request, but that decision remains S1 production without current-organization visibility or binding portfolio-level resource rights. - Evidence: subagent single-run invocation; session-specific quit and active task list; bounded local agent steps. - Basis: Bounded negative after inspecting apparent parent-control affordances. - Confidence: Medium-high. - Caveats: A custom app can assemble an S3 using the hooks and child results; that would be a different organizational boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No independently sourced audit of operational claims that returns a corrective finding to a distinct current-control owner is evidenced. - Disturbance / variety regulated: Model or tool outputs may be wrong; tape events, tool failures and optional hooks expose the producer&#39;s own record, not independent verification. - Decisive decision or feedback right: Operator/plugins may inspect traces or reject tool calls, but the first-party runtime has no separate auditor deciding the credibility of S1 reports against independent ground truth. - Decision owner: None for an S3-qualified audit channel; producer agent owns task output and caller owns external tests. - Supporting / enforcement mechanisms: Tape entries, tracing, beforetoolcall and aftertoolcall, event subscriptions, error notifications and SDK test fixtures. - Closure path: Producer&#39;s tool result/event is logged and fed to its own loop; no separate independent evidence check → audit opinion → corrective S3 control return is wired. - Why this is / is not agent-owned: Trace creation and permission checks are deterministic observability/execution controls, not an autonomous independent challenge to production claims. - Evidence: built-in tool hook; agent step events; tool traces. - Basis: Bounded negative first-party production and observation review. - Confidence: Medium-high. - Caveats: Future custom reviewer/plugin functionality should be assessed at its own operating boundary, with separate evidence rights.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No first-party loop senses prospective outside changes, selects future organizational adaptations and returns adopted capability changes to present operation. - Disturbance / variety regulated: Model/tool/provider shifts and emerging user needs may require future changes, but the runtime responds to current tasks and loads operator-configured capabilities. - Decisive decision or feedback right: Operators select model, tools and skills; model calls/retries within a task have only current-request authority. - Decision owner: Developer/operator for installed capacity and configuration, not a dedicated prospective S4 owner. - Supporting / enforcement mechanisms: Model selection, skill discovery, deferred tool loading, plugin registration, setmodel, context handoff and web fetching as a task tool. - Closure path: Operator changes tools/provider/skills and runs again; present-task fetch/feedback can inform next local answer but not strategic adoption based on future-environment appraisal. - Why this is / is not agent-owned: An S1 may research a future-facing question, but its output is not a first-party future capability governance cycle. - Evidence: agent skill/tool scope; built-in tool/provider controls; local context recovery. - Basis: Bounded negative on operating, capability and extension surfaces. - Confidence: Medium-high. - Caveats: A larger organization may separately build environmental intelligence with these tools; standard Bub does not evidence that circuit.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No ultimate identity/policy governance channel with legitimate authority, escalation and binding return is instantiated by the shipped system. - Disturbance / variety regulated: Unsafe tools, unexpected user messages and forbidden capabilities are addressed by first-party hooks, allowlists and operator configuration, not identity-level constitutional arbitration. - Decisive decision or feedback right: Operators configure tool/model access; plugin tool-call decisions can block/rewrite individual calls. No distinguished S5 holder adjudicates conflicting mission/identity rules and returns binding system policy. - Decision owner: Outside operator/developer for application policy; model work cell for task-level responses, not S5. - Supporting / enforcement mechanisms: allowedtools/allowedskills, beforetoolcall interception, ToolCallDecision, CLI quit and channel admission hooks. - Closure path: A disallowed tool call can be refused or a message queued/dropped; nothing escalates a normative identity dispute to a legitimate final authority with durable policy revision. - Why this is / is not agent-owned: Configured constraints operate within S1 tasks; an interactive user or plugin is not automatically a defined constitutional authority. - Evidence: turn capability scope; tool interception; channel admission. - Basis: Bounded negative on first-party operator and hook policy interfaces. - Confidence: Medium-high. - Caveats: External deployment governance cannot be imported as runtime S5 merely because a human operator exists.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/0298deac01c97c8eb11fdede4a23ff799d679fe9/assessments/bu/bub.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 0298deac01c97c8eb11fdede4a23ff799d679fe9\">0298dea &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-04T16:12:03+03:00\"><th scope=\"row\"><a href=\"https://github.com/ishaan1013/shadow\" target=\"_blank\" rel=\"noopener\">Shadow</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-04\">2026-10-04</time></td><td class=\"review-ref\"><a href=\"https://github.com/ishaan1013/shadow/tree/96e7b187951d66740dcd7d0bf3d5f94f5d09ed41\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 96e7b187951d66740dcd7d0bf3d5f94f5d09ed41\">96e7b18 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform environment-facing software-engineering work in a task-scoped repository workspace and deliver resulting changes. - Disturbance / variety regulated: heterogeneous user requests, repository structure, file/Git state, tool/terminal/search output, provider responses, implementation failures, context/history and changing task evidence. - Decisive decision or feedback right: choose which files/evidence to inspect, what terminal/search/edit action to execute, how to revise work from tool results, what TODO/memory action to take and when to stop responding. - Decision owner: the model-backed Shadow coding agent in the first-party streamText multi-step loop. - Supporting / enforcement mechanisms: first-party tool schemas/executors; task/workspace initialization; local/remote execution abstraction; TODOs; repository memory; semantic search; task status; checkpoints/history; Git commit/push and PR delivery. - Closure path: task + workspace/session context → model chooses a tool/action → Shadow executes it → result is returned inside the same multi-step model stream → model chooses subsequent action or completes → Shadow persists/delivers resulting workspace changes. - Boundary reachability: normal Shadow task execution directly wires the model to built-in coding tools with maxSteps: 100; no downstream orchestration code is required. - Why this is / is not agent-owned: removing the model-backed actor leaves workspace/tool/storage/delivery machinery but removes the open-ended coding judgment that selects and sequences work. - Evidence: stream-processor.ts; tools/index.ts; chat.ts. - Basis: explicit + structural. - Confidence: high. - Caveats: model inference is provider-backed; Shadow is credited for the first-party agent/tool/feedback organization and execution boundary.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material same-recursion inter-S1 coordination function was established. - Disturbance / variety regulated: not established at S2 level. Shadow isolates task workspaces, but reviewed evidence does not establish distinct production S1 units inside one task organization whose mutual interference is specifically attenuated by a first-party coordination relation. - Decisive decision or feedback right: not established. - Decision owner: not established. - Supporting / enforcement mechanisms: per-task workspaces/branches; Kata/QEMU isolation; task initialization/status; queued task actions. - Closure path: not applicable; no distinct-S1 interference → coordination response → changed subsequent S1 behavior loop was found. - Why this is / is not agent-owned: workspace isolation is primarily task/environment containment. Independent hosted tasks are not promoted into one organization without evidence of a shared same-recursion operational objective and interference relation. - Evidence: README.md; chat.ts. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: a larger deployment could coordinate multiple Shadow tasks externally; that organization is outside this task-level assessment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct whole-organization current-control function was established. - Disturbance / variety regulated: task status, initialization state, active streams, queued actions, cleanup, workspace availability and background services are tracked, but these are lifecycle/runtime controls around the focal task rather than whole-system operational management. - Decisive decision or feedback right: not established at S3 level. - Decision owner: not established. - Supporting / enforcement mechanisms: task statuses; active stream/cancel/queue maps; initialization engine; cleanup scheduling; background service manager; TODO state; Git/PR state. - Closure path: not applicable; no whole-system current view plus substantive organization-wide resource/priority/commitment intervention loop was reconstructed. - Why this is / is not agent-owned: the model owns coding decisions inside S1; task lifecycle state and scheduling are deterministic/operator-driven mechanisms. - Evidence: chat.ts; README.md. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: real-time task tracking is operationally useful but does not by itself satisfy the stronger S3 closure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party complementary audit actor/path distinct from the producing S1 was established. - Disturbance / variety regulated: ordinary tool errors, command results and generated PR metadata can expose problems, but no separate reviewer independently audits the producing agent&#39;s correctness/completion claim. - Decisive decision or feedback right: not established. - Decision owner: not established. - Supporting / enforcement mechanisms: command/tool validation; Git diff/commit generation; PR snapshot creation; task status; ordinary model self-observation. - Closure path: not applicable; no producing-S1 claim → complementary independent evidence path → audit verdict → corrective return loop was found. - Why this is / is not agent-owned: command/security validation is deterministic enforcement and PR generation summarizes/delivers changes; neither is a separate autonomous complementary auditor. - Evidence: chat.ts; pull-requests.ts. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: a user can review the draft PR externally; that external review is not a first-party autonomous S3 path.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material outside-and-future intelligence/adaptation loop was established. - Disturbance / variety regulated: repository-specific knowledge can persist across tasks through memories, and semantic/wiki context can improve later operation, but no explicit prospective environmental-modeling and adaptation-selection function was reconstructed. - Decisive decision or feedback right: not established at S4 level. - Decision owner: not established. - Supporting / enforcement mechanisms: addmemory, listmemories, removememory; automatic memory injection into later prompts; Shadow Wiki; optional semantic indexing; persisted task history. - Closure path: not applicable; no external/future distinction → adaptation-option generation → autonomous selection → persistent organizational capability/strategy change → later operation loop was found. - Why this is / is not agent-owned: the coding agent may decide to save useful facts, and those facts are later reused, but remembering operational knowledge is not itself the stronger prospective adaptation function. - Evidence: tools/index.ts; memory-service.ts; README.md. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: persistence is substantial; the negative classification is specifically about S4&#39;s prospective adaptation closure, not about whether Shadow learns/reuses repository facts colloquially.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material identity/ultimate-policy decision loop was established. - Disturbance / variety regulated: custom rules, command security, workspace boundaries, user settings, model/provider choice and auto-PR settings constrain operation, but they are task/runtime policy rather than identity-level governance. - Decisive decision or feedback right: not established for a genuine identity/ultimate-policy issue. - Decision owner: user/deployment/project configuration for relevant constraints; deterministic Shadow mechanisms enforce those selections. - Supporting / enforcement mechanisms: custom rules; command validation; workspace path protection; user settings; model selection; local/remote mode; auto-PR option. - Closure path: not applicable at S5 level; no identity/policy conflict → legitimate ultimate authority → authoritative decision → returned organizational operation loop was established. - Why this is / is not agent-owned: the coding model does not own Shadow&#39;s ultimate policy/identity boundary, and enforcement of configured restrictions is not itself S5. - Evidence: README.md; chat.ts. - Basis: explicit + structural absence review. - Confidence: high. - Caveats: a broader organization may govern Shadow through external policy; that parent is not imported without a function-specific closed loop.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/0127536997698de17d4e0decbd3baf4cf3f3d46e/assessments/shadow.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 0127536997698de17d4e0decbd3baf4cf3f3d46e\">0127536 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-10-12T17:27:48+03:00\"><th scope=\"row\"><a href=\"https://github.com/SWE-agent/mini-swe-agent\" target=\"_blank\" rel=\"noopener\">mini-swe-agent</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-12\">2026-10-12</time></td><td class=\"review-ref\"><a href=\"https://github.com/SWE-agent/mini-swe-agent/tree/04d809ceab9df28f9adaed044884180159172930\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 04d809ceab9df28f9adaed044884180159172930\">04d809c &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: Direct first-party model/tool turn loop performs a coding task against a local or container execution environment. - Disturbance / variety regulated: Uncertain task request, shell/tool errors, changing workspace files and model responses. - Decisive decision or feedback right: Select environment commands/actions from current model context and revise after observed results. - Decision owner: Model-driven DefaultAgent (or InteractiveAgent inheriting it) makes task-specific execution choices. - Supporting / enforcement mechanisms: Model.query, Environment.execute, Jinja templates, observation messages, exit/step/time/cost bounds. - Closure path: Task and prompt history → model proposes actions → environment executes → returned observations → next model query or stop. - Boundary reachability: First-party CLI entrypoint constructs DefaultAgent/InteractiveAgent and invokes run; actual shell/environment execution occurs through executeactions, not a toy graph. - Why this is / is not agent-owned: Task-specific model choice drives actual environment operations; deterministic limits and environment runners are supporting mechanisms. - Evidence: src/minisweagent/agents/default.py; src/minisweagent/environments/local.py; src/minisweagent/models/litellmmodel.py; src/minisweagent/run/mini.py - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No first-party inter-S1 interference attenuation at the declared single-agent distribution boundary. - Distinct S1 units: Only the one current DefaultAgent/InteractiveAgent is evidenced; external separate invocations are not owned subagents. - Inter-S1 disturbance: No shipped interacting worker fleet whose conflicts/oscillations require coordination. - Attenuating coordination relation: No joint-work arbitration, conflict feedback or external worker resource rights found. - Feedback into subsequent S1 behaviour: Own action observations feed only the same S1 agent. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: A single model turn/action loop is not an S2 coordination relation. - Disturbance / variety regulated: Potential multi-agent content/file collisions are absent as a coordinated first-party operating mode; a user can separately launch processes outside this one-agent recursion. - Decisive decision or feedback right: No inter-worker arbitration right among distinct operating agents is implemented. - Decision owner: No S2 owner at the declared one-agent boundary. - Supporting / enforcement mechanisms: One model/agent and one Environment; step loop serially dispatches selected commands. - Closure path: Only a single agent&#39;s actions and observations return to itself; no cross-agent conflict or corrected coordination path. - Why this is / is not agent-owned: No first-party function-specific higher-level owner or full closure exists in the inspected supported single-agent modes. - Evidence: src/minisweagent/agents/default.py; src/minisweagent/agents/interactive.py; src/minisweagent/run/mini.py; src/minisweagent/environments/local.py - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No separate whole-current operational director controlling a plurality of independently acting agents or resource commitments. - Whole-system current view: Only one agent&#39;s messages, execution count, cost, wall time and command observations. - Current-control decision scope: Individual command/turn limits, not team resources and commitments. - Disturbance / variety regulated: Task step/time/cost state and human command confirmations apply to one running task rather than team portfolio. - Decisive decision or feedback right: Model selects the next operating step, while static limits terminate; no above-S1 resource bargaining/priority intervention. - Decision owner: None established at a higher team recursion; the single operating agent owns task-local decisions. - Supporting / enforcement mechanisms: steplimit, costlimit, walltimelimitseconds, InteractiveAgent prompt and parent process. - Closure path: Step cost/errors → terminate or next action of same S1; no independent worker reports → whole-system control → modified shared commitments. - Why this is / is not agent-owned: No first-party function-specific higher-level owner or full closure exists in the inspected supported single-agent modes. - Evidence: src/minisweagent/agents/default.py; src/minisweagent/agents/interactive.py; src/minisweagent/run/mini.py; src/minisweagent/config/default.yaml - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No separate, sufficiently independent complementary inspection of operational reality challenging produced task claims in the bundled agent. - Claim being audited: Model&#39;s code/task completion claim. - Ordinary reporting path: Model messages and its own environment command output. - Complementary access path: No independent source/artifact observation owner, only ordinary tool observations. - Independence boundary: Separate reviewer or audit process unavailable in standard distribution. - Who acts on findings: None; ordinary tool errors alter the same agent&#39;s next actions. - Disturbance / variety regulated: Incorrect task completion/code is not separately audited by a first-party observer; ordinary command feedback remains in S1. - Decisive decision or feedback right: No distinct audit sampling/judgment right beyond ordinary model/tool observations and optional human confirmation of commands. - Decision owner: None; model observes its own executed commands and optional user approves individual actions. - Supporting / enforcement mechanisms: Command stdout/stderr and exit observations, serialized trajectory and ordinary task feedback. - Closure path: Tool execution output goes to its own producing model, not independently sampled and judged with corrective control. - Why this is / is not agent-owned: No first-party function-specific higher-level owner or full closure exists in the inspected supported single-agent modes. - Evidence: src/minisweagent/agents/default.py; src/minisweagent/agents/interactive.py; src/minisweagent/environments/local.py; src/minisweagent/run/mini.py - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No first-party outside-and-prospective organizational capability adaptation loop beyond immediate coding task work. - External distinction: User task and model-supplied context are not ongoing external environmental horizon sensing. - Future / prospective distinction: Serialized trajectories and static templates alone are not future capability redesign. - Adaptation option generated: No qualifying organizational future-adaptation option. - Path back into current capability / S3: No separate capability-changing return beyond ordinary new prompt. - Disturbance / variety regulated: Future environment opportunity/threat and system redesign are outside this task-bounded loop. - Decisive decision or feedback right: Agent can adapt the next command, but cannot select and apply a future organizational capability adaptation in a shipped separate function. - Decision owner: No prospective S4 authority; user chooses static model, environment and configuration. - Supporting / enforcement mechanisms: Config YAML, model provider wrapper, task conversation and saved trajectory. - Closure path: Messages inform the current task only; no external future observation → adaptation option → changed operational capability loop. - Why this is / is not agent-owned: No first-party function-specific higher-level owner or full closure exists in the inspected supported single-agent modes. - Evidence: src/minisweagent/agents/default.py; src/minisweagent/models/litellmmodel.py; src/minisweagent/config/default.yaml; src/minisweagent/run/mini.py - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No ultimate organizational identity/policy governance loop in the single-agent standard distribution. - Identity / ultimate-policy issue: Who chooses and revises overarching organization purpose and authority. - Ultimate authority in each claimed mode: Outside user, not an operational first-party parent governance loop. - Return-to-operation path: Action confirmation governs one command, not ultimate organizational policy. - Disturbance / variety regulated: Command approvals, tool limits and user-chosen settings bound local execution, not the systemic identity/purpose of an agent organization. - Decisive decision or feedback right: User may approve/deny an individual action and set static modes, not govern ultimate purpose via an operational returned decision loop. - Decision owner: User/developer external to the assessed single-agent organization; no first-party parent S5 closure. - Supporting / enforcement mechanisms: InteractiveAgent human/confirm/yolo mode and regular-expression allowlist, task template, execution cost and step limits. - Closure path: Command action → user allow/deny → one action executes or cancels; no ultimate purpose/identity review and return that governs an organization. - Why this is / is not agent-owned: No first-party function-specific higher-level owner or full closure exists in the inspected supported single-agent modes. - Evidence: src/minisweagent/agents/interactive.py; src/minisweagent/config/default.yaml; src/minisweagent/agents/default.py; src/minisweagent/run/mini.py - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/b20dddb7930735d5399471b0299ec0054f57df35/assessments/mini-swe-agent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit b20dddb7930735d5399471b0299ec0054f57df35\">b20dddb &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-27T00:36:58+03:00\"><th scope=\"row\"><a href=\"https://github.com/CenterForOpenScience/llm-benchmarking\" target=\"_blank\" rel=\"noopener\">ReplicatorAgent</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-27\">2026-09-27</time></td><td class=\"review-ref\"><a href=\"https://github.com/CenterForOpenScience/llm-benchmarking/tree/fb6a804fd710764f3ad3c8b84e1323c2804c4776\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision fb6a804fd710764f3ad3c8b84e1323c2804c4776\">fb6a804 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: carry out the substantive scientific replication operation from source-study extraction through replication design, executable analysis/debugging and result interpretation. - Disturbance / variety regulated: heterogeneous study files/data, incomplete replication metadata, analysis-design uncertainty, package/environment incompatibilities, Docker build failures, generated-code/runtime errors, statistical outputs and ambiguous result/log evidence. - Decisive decision or feedback right: choose the replication design and analysis implementation, decide from tool/build/runtime observations what files/configuration/code to inspect or modify, decide how to retry failed execution, and decide what produced evidence means for the final replication interpretation. - Decision owner: the first-party model-driven ReplicatorAgent/ReAct stages; the human operator owns only the bounded authorization gate before executing the already selected analysis command. - Supporting / enforcement mechanisms: first-party tool schemas/action dispatch, study-scoped file access, JSON templates, Docker generation/build/run tools, process/container isolation, checkpoint/turn limits, persisted stage files/metadata and mandatory human approval. - Closure path: supplied study evidence -&gt; agent extracts/designs replication -&gt; Docker/code action is prepared -&gt; human authorization gate permits execution -&gt; environment returns build/runtime/result evidence -&gt; agent diagnoses/fixes/retries as needed -&gt; interpreter inspects the resulting evidence -&gt; final replication report/structured interpretation is produced. - Boundary reachability: make pipeline-easy directly invokes the Extract, Design, Execute and Interpret stages in the standard distribution; Design/Execute/Interpret use the shipped runreactloop and first-party tools without requiring benchmark validator orchestration. - Why this is / is not agent-owned: deterministic code enforces tool calls, sandboxing, stage order and the safety approval gate, while the context-sensitive scientific design, code/config repair, retry and interpretation choices are model-driven. Removing the model decision path while keeping the human approval and Docker machinery would not produce materially the same discretionary replication choices. - Evidence: replicatorbench/Makefile; replicatorbench/core/agent.py; replicatorbench/generator/designagent.py; replicatorbench/generator/executeagent.py; replicatorbench/interpreter/agent.py. - Basis: explicit + structural. - Confidence: high. - Caveats: the standard Execute path cannot cross its actual-analysis authorization gate without human approval. This is treated as a bounded safety/permission constraint on an otherwise agent-owned operation, not a separate published S1 Parent state, which Methodology 0.3.6 does not define.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no qualifying inter-S1 interference-attenuation function is established at the declared one-replication recursion. - Disturbance / variety regulated: none qualifying; Extract, Design, Execute and Interpret are sequential stages contributing to one operational outcome rather than distinct concurrently accountable S1 units with a concrete interaction disturbance. - Decisive decision or feedback right: none established for S2. - Decision owner: none established. - Supporting / enforcement mechanisms: Makefile sequencing, persisted stage artifacts and tool/state transfer are workflow composition, not S2. - Closure path: no material inter-S1 disturbance -&gt; coordination decision -&gt; changed affected-S1 behaviour path closes. - Why this is / is not agent-owned: multiple modules/agents and artifact handoffs do not establish the coordination function without a specific cross-operation conflict/oscillation/interference witness. - Evidence: replicatorbench/Makefile; replicatorbench/README.md. - Basis: structural absence. - Confidence: high. - Caveats: parallel external benchmark execution would define a different operational boundary if independently accountable replication workers and an interference problem were introduced.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no distinct superior whole-system current-control actor is established above the single replication operation. - Disturbance / variety regulated: stage failures, build/runtime failures and current execution state are regulated, but either by scripted stage order or within the same S1 Execute/debug loop. - Decisive decision or feedback right: no autonomous actor is evidenced with a whole-system current view and broad discretionary authority over multiple operational units/shared current resources, priorities, commitments or constraints. - Decision owner: none established for qualifying S3. - Supporting / enforcement mechanisms: Makefile stage ordering, execute checkpoints, turn limits, Docker lifecycle and the human safety approval gate. - Closure path: scripted stages and local S1 error/retry feedback determine progression; no separate management loop over a current operational whole closes. - Why this is / is not agent-owned: the execute agent&#39;s debugging authority is task-local S1 recovery. The Makefile/orchestrator transports and enforces stage progression but does not make contextual whole-system management decisions. - Evidence: replicatorbench/Makefile; replicatorbench/generator/executeagent.py. - Basis: structural absence. - Confidence: high. - Caveats: the mandatory human approval is authorization of one execution boundary, not evidence of a first-party S3 parent loop with whole-system current control.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: the repository contains a materially separate LLM-as-judge validator, but the standalone ReplicatorAgent pipeline does not close validator findings back into corrective operation. - Disturbance / variety regulated: validator commands can detect extraction/design/execution/interpretation disagreement against benchmark ground truth, but those findings serve benchmark evaluation rather than the standard agent&#39;s corrective feedback path. - Decisive decision or feedback right: none established in the standard pipeline for an independent auditor whose findings trigger a later operational correction. - Decision owner: none established for qualifying S3 inside ReplicatorAgent. - Supporting / enforcement mechanisms: replicatorbench/validator/, expert-annotated ground truth, stage-specific evaluate commands and aggregate evaluation reports are adjacent evaluation infrastructure. - Closure path: pipeline-easy ends after Interpret; validator execution requires separate evaluate- commands and no first-party path returns its findings into Extract/Design/Execute/Interpret modification and re-run. - Why this is / is not agent-owned: complementary evaluation evidence exists, but S3 requires the organizational feedback function, not merely an independent benchmark scorer in the same repository. - Evidence: replicatorbench/README.md; replicatorbench/Makefile. - Basis: explicit + structural absence. - Confidence: high. - Caveats: a composed system that automatically applies validator findings and reruns the affected operational stage could establish S3; that wiring is not present in the frozen standard pipeline.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no qualifying external-and-prospective adaptation loop that changes future/current organizational capability is established in the standard ReplicatorAgent pipeline. - Disturbance / variety regulated: optional web search can identify external data resources useful for the current replication, and Design chooses a plan for the current study, but neither establishes a separate prospective organizational adaptation function. - Decisive decision or feedback right: none established for S4. - Decision owner: none established for qualifying S4. - Supporting / enforcement mechanisms: separately invokable web-search, Responses API web search, current-study design agent, study documents and generated replication plan. - Closure path: no standard external evidence -&gt; prospective adaptation option -&gt; changed installed/current organizational capability loop closes. pipeline-easy does not invoke web-search, and search output is not mechanically returned into a persistent adaptation path. - Why this is / is not agent-owned: searching for datasets/resources needed to execute the current assigned replication and planning that replication are current-task S1 research work, not S4 merely because they look outward or ahead. - Evidence: replicatorbench/README.md; replicatorbench/Makefile; replicatorbench/infoextractor/extractor.py; replicatorbench/generator/designagent.py. - Basis: explicit + structural absence. - Confidence: high. - Caveats: web-search may enrich a manually composed replication workflow, but optional information retrieval for a current study is not enough to publish S4 without a prospective adaptation closure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party runtime identity/ultimate-policy authority is established. - Disturbance / variety regulated: the supplied study/claim, prompts/templates, tier/code mode, model choice, sandbox restrictions and human execution authorization constrain the replication but do not constitute an identity-level decision loop. - Decisive decision or feedback right: define or revise the ultimate purpose/identity/top-level policy of the replication organization beyond the externally supplied task and static configuration. - Decision owner: external user/developer/configuration; no qualifying first-party S5 owner is established. - Supporting / enforcement mechanisms: CLI/Make parameters, static prompts/templates, study path, Docker restrictions, file-operation policies, model API configuration and human authorization. - Closure path: no material first-party identity/ultimate-policy issue -&gt; authoritative decision -&gt; return-to-operation loop closes. - Why this is / is not agent-owned: ReplicatorAgent autonomously decides how to reproduce the supplied claim within configured constraints, not what ultimate organizational identity/purpose it should pursue. - Evidence: replicatorbench/README.md; replicatorbench/generator/executeagent.py; replicatorbench/generator/designagent.py. - Basis: explicit + structural absence. - Confidence: high. - Caveats: human approval of a concrete command is not identity/ultimate-policy closure and therefore is not promoted to S5=P.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/aae05832c1be91537796185d81c590ea219a2e04/assessments/replicator-agent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit aae05832c1be91537796185d81c590ea219a2e04\">aae0583 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-09-28T19:46:13Z\"><th scope=\"row\"><a href=\"https://github.com/willdady/platypus\" target=\"_blank\" rel=\"noopener\">Platypus</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-28\">2026-09-28</time></td><td class=\"review-ref\"><a href=\"https://github.com/willdady/platypus/tree/5dda4dcdb92c209c8c8df953f0e9261cd018c2d7\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 5dda4dcdb92c209c8c8df953f0e9261cd018c2d7\">5dda4dc &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: perform substantive Workspace work through model-driven Agent runs that interpret an instruction/request, select tools, observe results and continue until the bounded run outcome is produced. - Disturbance / variety regulated: heterogeneous user and Trigger instructions, shared Workspace resource state, tool/MCP/browser/sandbox observations, external information, provider/model variation and task-specific failures. - Decisive decision or feedback right: choose semantic next actions and tool calls from the current objective/context, interpret returned observations and revise later actions within the run. - Decision owner: the model-driven Agent resolved and driven through Platypus&#39;s first-party run/turn machinery. - Supporting / enforcement mechanisms: AgentRunner, prepareChatTurn, run registry/lifecycle, model generation limits, first-party tool assembly, scoped Workspace principals, sandbox/MCP/tool execution and Trigger sinks/timeouts. - Closure path: user or Trigger instruction → first-party turn resolves Agent/model/tools/context → model selects action/tool → observation returns into the model loop → later action changes from the observation → Chat/Trigger outcome is persisted or emitted. - Boundary reachability: ordinary interactive Chats and first-party Trigger firing both invoke the shipped Agent run path. Trigger execution explicitly calls agentRunner.generate under a Workspace-scoped Trigger principal. - Why this is / is not agent-owned: removing the model actor while retaining schedules, API routes, tool schemas, persistence and run lifecycle leaves execution infrastructure but removes the semantic task decisions that produce the substantive operational result. - Evidence: README.md; apps/backend/src/runs/agent-runner.ts; apps/backend/src/services/trigger-firing.ts; apps/docs/content/concepts/agents.mdx. - Basis: explicit + structural. - Confidence: high. - Caveats: external model/provider internals remain dependencies; A credits the model actor reached through Platypus&#39;s first-party harness, not autonomous ownership by deterministic run support code.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate recursive interference between event-driven operational Agent runs acting on the same Workspace entity by bounding repeated Trigger firings in a rolling window. - Disturbance / variety regulated: two event Triggers can hand one record back and forth, each Agent write producing the next event after the previous run finishes; this can create an unbounded multi-run oscillation that repeatedly consumes full Agent drives even though the single-Agent self-actor guard is never crossed. - Decisive decision or feedback right: suppress the next firing for a specific Trigger × entity once the deployment-level rolling run ceiling is reached, preventing another Agent run from starting. - Decision owner: deterministic first-party Trigger breaker/runtime policy. - Supporting / enforcement mechanisms: event causation tracking, self-actor guard, event debounce, triggerrun history, rolling maxRuns/windowSeconds, suppression records and retention that preserves the counted evidence window. - Closure path: distinct Trigger-backed Agent operations mutate a shared entity → later matching Workspace event attempts another Trigger firing → breaker reads recent per-Trigger/per-entity run history → excess firing is recorded as suppressed before Agent invocation → the oscillating operational chain is attenuated. - Boundary reachability: fireTrigger checks shouldSuppressTriggerRun on ordinary event firings and calls suppressTriggerRun instead of runTrigger; the breaker is a standing runtime property configured at deployment boot, not a test-only mechanism. - Why this is / is not agent-owned: Agents cause the operational writes/events, but the coordination decision that bounds the inter-operation feedback loop is deterministic first-party runtime logic and operator-configured ceiling. No model actor owns the breaker judgment, so the state is C, not A. - Distinct S1 units: separate Trigger-fired model-driven Agent runs in the same Workspace, potentially using different Triggers/Agents, each capable of substantive mutations on shared Workspace entities. - Inter-S1 disturbance: repeated event causation can produce a feedback oscillation in which two Trigger/Agent paths hand the same entity back and forth and repeatedly invoke full model/tool runs. - Attenuating coordination relation: a rolling per-Trigger × entity run-rate breaker suppresses excess event firings before a further S1 Agent run begins; a short debounce and self-actor guard provide additional but incomplete attenuation. - Feedback into subsequent S1 behaviour: once the ceiling is reached, the next matching operational unit is not invoked at all; later Agent behaviour is therefore changed by the accumulated interaction history rather than merely logged. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the implementation and comments name the cross-Trigger feedback-cycle failure mode, explain why self-actor and debounce are insufficient, and apply a mechanism specifically to attenuate that inter-operation oscillation. The finding does not rely on Sub-Agent routing, queues or shared Boards alone. - Evidence: apps/backend/src/services/trigger-breaker.ts; apps/backend/src/services/trigger-firing.ts; apps/backend/src/services/event-dispatch.ts. - Basis: explicit + structural. - Confidence: high. - Caveats: S2 is scoped to the event-driven Trigger organization. Sub-Agent delegation by itself is not treated as S2, and no autonomous coordination owner is inferred from model-driven S1 actors.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no material first-party Workspace-wide current-control function is established at the assessed recursion. - Disturbance / variety regulated: individual Agent runs have step/time limits, Trigger runs have lifecycle/breaker controls, and a coordinator Agent can delegate a bounded task to specialists; these mechanisms regulate local execution but do not constitute a standing current-control function for the Workspace as a whole. - Decisive decision or feedback right: no first-party actor/path was found that receives a whole-Workspace current view of operational Agents/commitments/resources and closes decisions over their current priorities, allocation, constraints or synergy on behalf of the whole. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: Agent/Trigger CRUD, Agent discovery, run registries and run lists, Trigger scheduler/breaker, Boards/Dashboards, Sub-Agent delegation, generation/time limits and owner/admin controls. - Closure path: not applicable for the negative finding. - Why this is / is not agent-owned: a top-level Agent may coordinate its own configured Sub-Agents inside one task and an Agent may be granted generic management tools, but neither is a first-party Workspace regulator at this recursion. Tool availability plus user-authored instructions would require composition of the missing function rather than demonstrate it in the shipped organizational path. - Evidence: apps/docs/content/building-with-platypus/agents.mdx; apps/backend/src/tools/agent-management.ts; apps/backend/src/runs/agent-runner.ts. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: at the narrower recursion of one configured coordinator-plus-specialists task, the parent Agent may exercise local orchestration. This assessment does not lift that nested task role into Workspace-level S3.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party complementary-audit function is established at Workspace recursion. - Disturbance / variety regulated: no positive S3 claim is made. Platypus can host an Agent whose user-authored role is reviewing/fact-checking, but ordinary configurable specialist delegation is not itself an independent audit architecture. - Decisive decision or feedback right: no shipped path was found in which an ordinary S1 outcome is automatically or structurally challenged through a distinct complementary evidence channel and the audit finding returns into correction/current control. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: Sub-Agent delegation, run status/events, tool-result records, Trigger run pages and generic reviewer/fact-checker Agent configurations are available but insufficient for positive S3 closure. - Closure path: not applicable for the negative finding. - Why this is / is not agent-owned: a user can configure a specialist called a reviewer and ask a parent Agent to call it, but that is task composition chosen by the user/model, not a first-party complementary audit path with established independence, evidence access and corrective closure. - Evidence: apps/docs/content/concepts/agents.mdx; apps/docs/content/building-with-platypus/agents.mdx; apps/backend/src/runs/run-events.ts. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: a specific user-created multi-agent configuration could implement audit semantics using Platypus primitives. Repository-relative assessment does not credit arbitrary downstream compositions as a shipped first-party S3 function.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material external-and-prospective adaptation loop is established at the assessed Workspace recursion. - Disturbance / variety regulated: Platypus can search the web, call MCP/data sources, react to Workspace events and retain Memory from prior Chats, but those capabilities support current task execution or internally retrospective recall rather than a distinct future/environment adaptation function. - Decisive decision or feedback right: no first-party path was found that models material external/future distinctions, develops adaptation options for the Workspace organization from them and returns those options into present S3/capability policy as a closed organizational conversation. - Decision owner: none established for S4. - Supporting / enforcement mechanisms: web/MCP tools, scheduled/event Triggers, Memory extraction/retrieval, user/Workspace Context, Skills and Agent management. - Closure path: not applicable for the negative finding. - Why this is / is not agent-owned: model Agents can research outside information as part of S1 and may use generic management tools afterward if configured, but the repository does not wire those primitives into a distinct prospective adaptation role/loop at Workspace level. - Evidence: apps/docs/content/concepts/memory-and-context.mdx; README.md; apps/docs/content/building-with-platypus/triggers.mdx. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: generic composability may permit a downstream user to build an S4-like research/adaptation workflow; that is not credited without a first-party closed function in the reviewed repository.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: maintain durable Workspace-level mission/identity framing that is injected into later Agent operation across the Workspace. - Disturbance / variety regulated: drift or disagreement about the Workspace&#39;s standing domain, purpose, terminology and shared framing that all Agent runs should operate within. - Decisive decision or feedback right: set or revise the Workspace context field that Platypus injects into the Workspace fragment of the system prompt for subsequent operation. - Decision owner: legitimate parent authority — the Workspace Owner or Organization Admin through the supported Workspace update surface. - Supporting / enforcement mechanisms: Workspace ownership/authorization, workspaceUpdateSchema, persisted Workspace row, first-party prompt-context resolution and workspaceFragment composition. - Closure path: Workspace identity/policy issue → owner/admin edits the persisted Workspace Context → subsequent turn/run resolution reads current Workspace state → system-prompt composition emits the Workspace id/context fragment → later model-driven S1 operation is framed by the changed Workspace policy/identity. - Boundary reachability: the normal Workspace update route is available to authorized Workspace administration, and the canonical system-prompt contract states that the Workspace fragment is always part of the composed prompt and includes Workspace Context when present. - Why this is / is not agent-owned: no inspected first-party tool gives ordinary Workspace Agents legitimate authority to rewrite the Workspace&#39;s authoritative context field. Agent Instructions and agent-management tools govern constituent Agents, not the Workspace-wide identity surface. The decisive S5 right therefore remains parent-owned. - Identity / ultimate-policy issue: what this Workspace is for and the standing shared framing/terminology under which every Agent operation in the Workspace should interpret its work. - Ultimate authority in each claimed mode: Parent (P) — Workspace Owner or Organization Admin authorized to update the Workspace record. - Return-to-operation path: parent update → persisted Workspace Context → first-party turn resolution → workspaceFragment in composed system prompt → subsequent Agent/Trigger runs operate with the changed shared framing. - Evidence: apps/docs/content/concepts/memory-and-context.mdx; apps/docs/content/concepts/system-prompt.mdx; apps/backend/src/system-prompt.ts; apps/backend/src/routes/workspace.ts. - Basis: explicit + structural. - Confidence: high. - Caveats: per-Agent Instructions are not used as the Workspace-level S5 witness because they govern constituent S1 configurations rather than the whole Workspace. Organization identity is an additional parent framing layer but is not needed to establish this P finding.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/cb30fe9c47fee3770fbb65e68e592f19fa3d6766/assessments/platypus.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit cb30fe9c47fee3770fbb65e68e592f19fa3d6766\">cb30fe9 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-09-17T23:12:14+03:00\"><th scope=\"row\"><a href=\"https://github.com/BloopAI/vibe-kanban\" target=\"_blank\" rel=\"noopener\">Vibe Kanban</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-17\">2026-09-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/BloopAI/vibe-kanban/tree/735654971bd396aa97b65166955678e4c34f8bf8\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 735654971bd396aa97b65166955678e4c34f8bf8\">7356549 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: A. Supported coding agents autonomously modify repositories inside Vibe Kanban-managed executions/workspaces.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: C. The runtime structurally excludes conflicting concurrent active execution in a workspace, attenuating the concrete disturbance of simultaneous mutation of the same operational workspace. This is deterministic/runtime-owned coordination rather than an autonomous S2 actor.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: —. Execution status, follow-ups and lifecycle transitions supervise individual runs but do not establish a separate whole-organization regulator owning shared current priorities/resources/commitments.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: —. Review/diff surfaces and human feedback are useful inspection mechanisms, but no materially independent first-party audit channel with autonomous corrective closure was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: —. No prospective environment-facing adaptation loop was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: —. Human review, PR creation and merge authority are task acceptance/control surfaces, not an organizational identity/ultimate-policy loop.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/aa0f4fc244d04c276678f55ed941376422a344af/assessments/vibe-kanban.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit aa0f4fc244d04c276678f55ed941376422a344af\">aa0f4fc &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-20T21:45:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/causalNLP/causal-agent\" target=\"_blank\" rel=\"noopener\">Causal AI Scientist (CAIS)</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/causalNLP/causal-agent/tree/2289e9e3c11376336dec027fd17269a46443a784\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 2289e9e3c11376336dec027fd17269a46443a784\">2289e9e &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: autonomously construct and execute a causal analysis from a dataset and query, including method/control choices and explanation of the resulting estimate. - Disturbance / variety regulated: variation in causal question, dataset schema/characteristics, candidate causal method, control variables, optional instruments, cleaning requirements, and estimator execution. - Decisive decision or feedback right: interpret the causal problem and select the method/variables/control structure that determines the analysis to execute. - Decision owner: model-assisted CAIS analysis components, especially query/dataset interpretation and LLM-backed method selection; the selected structure is then executed by first-party causal tools/estimators. - Supporting / enforcement mechanisms: tool wrappers, estimator library, data cleaning, typed models, optional IV discovery, deterministic estimator code, and provider transport. - Closure path: dataset/query observations feed the selection components; selected method/variables determine cleaning and execution; computed results feed the explanation generator and returned analysis. - Boundary reachability: this path is the current public CausalAgent.runanalysis() workflow, not a test or deprecated compatibility function. - Why this is / is not agent-owned: substantive interpretation/method-selection discretion is model-driven in the standard path; deterministic estimators execute the chosen causal analysis rather than owning that upstream decision. - Evidence: CausalAgent workflow, README workflow. - Basis: explicit + structural. - Confidence: high. - Caveats: CAIS can switch to rule-based method selection; the positive state is based on the first-party standard model-assisted mode exposed by llmmethodselection=True.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2 coordination function is established at the declared recursion. - Disturbance / variety regulated: not established. - Decisive decision or feedback right: not established. - Decision owner: not applicable. - Supporting / enforcement mechanisms: staged tool calls and specialist helpers pass structured state but do not evidence regulation of interference among distinct S1 operational units. - Closure path: not established. - Why this is / is not agent-owned: dataset analyzer, selector, critics, executor, and explainer are functional components of one causal-analysis operation; plurality of components is not an S2 witness. - Evidence: CausalAgent staged workflow. - Basis: structural negative finding. - Confidence: high. - Caveats: a future multi-analysis/team mode would need an actual inter-S1 disturbance and attenuation loop to qualify.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no material whole-system current-control function is established separately from task-local causal-method selection and pipeline sequencing. - Disturbance / variety regulated: not established at S3 scope. - Decisive decision or feedback right: not established at whole-system management scope. - Decision owner: not applicable. - Supporting / enforcement mechanisms: fixed stage order, method-selection logic, estimator availability checks, tool error handling, and optional flags regulate local task execution. - Closure path: local selections flow into the next analysis step, but no whole-system supervisory decision over resources, commitments, priorities, accountability, or cross-operation intervention is evidenced. - Why this is / is not agent-owned: choosing the causal method for the analysis is part of producing the S1 outcome; it is not automatically S3 simply because it chooses among methods. - Evidence: current runanalysis sequence. - Basis: structural negative finding. - Confidence: high. - Caveats: documentation calls out staged validation and feedback, but current pinned runtime integration controls the assessment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material, operationally closed complementary-audit function is established in the current standard CausalAgent path. - Disturbance / variety regulated: not established at S3 scope. - Decisive decision or feedback right: not established as an independent audit right over current operation. - Decision owner: not applicable. - Supporting / enforcement mechanisms: optional IV exclusion/independence critics and the repository&#39;s method-validator/assumption-check machinery provide validation primitives, but the current operating path does not close a separate complementary audit loop over executed S1 work. - Closure path: the current IV critics filter proposed instruments before method execution; the broader method-validator path is not invoked by runanalysis(). No independent audit finding is shown returning to whole-system control after observing operational reality. - Why this is / is not agent-owned: critic/validator naming is insufficient. The IV critics inspect candidate instrument plausibility inside ordinary method construction, and the current public validatemethod() is explicitly not in use. - Evidence: current CausalAgent including validatemethod() and runanalysis(), IV critics integration, method validation machinery. - Basis: structural negative finding. - Confidence: high. - Caveats: if the method-validator/assumption-check feedback loop becomes part of the supported current entry point, reassess its complementary access, organizational independence, judgment owner, and return-to-control closure rather than assigning S3 automatically.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party outside-and-then adaptation loop is established at the declared recursion. - Disturbance / variety regulated: not established at S4 scope. - Decisive decision or feedback right: not established. - Decision owner: not applicable. - Supporting / enforcement mechanisms: domain-informed prompts, candidate causal-method knowledge, IV hypothesis/critic reasoning, dataset analysis, and method alternatives help solve the current causal task. - Closure path: current data/query distinctions feed current analysis choices; no separately evidenced external/prospective sensing loop changes later system capability or research strategy. - Why this is / is not agent-owned: knowledge of multiple methods and generation of alternative suggestions are current problem-solving options, not by themselves S4. - Evidence: method validator, IV discovery, current CausalAgent. - Basis: structural negative finding. - Confidence: high. - Caveats: an external-literature or prospective adaptation loop that changes subsequent causal-analysis capability could change this state.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material first-party identity/ultimate-policy function is established at the declared causal-analysis recursion. - Disturbance / variety regulated: not established at S5 scope. - Decisive decision or feedback right: not established. - Decision owner: not applicable. - Supporting / enforcement mechanisms: user query, configuration, provider/model selection, causal-method library, prompts, and flags constrain the analysis. - Closure path: not established at identity/ultimate-policy scope. - Why this is / is not agent-owned: the user query defines the current analysis request; it does not establish a runtime governance loop for the system&#39;s identity or ultimate policy. - Evidence: CausalAgent constructor and run entry point, configuration. - Basis: structural negative finding. - Confidence: high. - Caveats: ordinary human choice of dataset/query/provider is not parent-governed S5.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c9da28372ac35ff5d8bc9a74679a6987a5d451df/assessments/cais.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c9da28372ac35ff5d8bc9a74679a6987a5d451df\">c9da283 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T04:01:58+03:00\"><th scope=\"row\"><a href=\"https://github.com/anthropics/claude-agent-sdk-python\" target=\"_blank\" rel=\"noopener\">Claude Agent SDK</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/anthropics/claude-agent-sdk-python/tree/37a52c9fb3f0271de017911914b0d42efea6267e\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 37a52c9fb3f0271de017911914b0d42efea6267e\">37a52c9 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: the normal SDK session supports autonomous tool selection/action over long-running coding or general tasks.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: specialist/subagent invocation is delegation. No first-party mechanism was established whose responsibility is regulating interference, oscillation or shared constraints among multiple autonomous S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: permissions, hooks and parent/subagent lifecycle controls constrain execution but do not constitute whole-system current authority over multiple S1 resources, priorities and commitments.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: hooks can observe or block operational events, but the hook callbacks and their authority are application-supplied. No autonomous, organizationally separate complementary audit channel is included by default.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: session state, hooks and specialist delegation concern current operation; no separate prospective environment-intelligence function that adapts future system capability was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: instructions, permissions, hooks and agent definitions remain developer/user-owned rather than an autonomous ultimate policy/identity authority.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c62c112b9468bc60e2a63b92623b0b69fd6248a6/assessments/claude-agent-sdk.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c62c112b9468bc60e2a63b92623b0b69fd6248a6\">c62c112 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-09-20T21:03:34Z\"><th scope=\"row\"><a href=\"https://github.com/manthanguptaa/water\" target=\"_blank\" rel=\"noopener\">Water</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/manthanguptaa/water/tree/454a86b79980877ed77d38ad1a150246a9bf1cf2\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 454a86b79980877ed77d38ad1a150246a9bf1cf2\">454a86b &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: - State: A - Function: autonomously execute an assigned task through a model-controlled Think-Act-Observe-Repeat loop using first-party Water tools and returned observations. - Disturbance / variety regulated: task ambiguity, changing tool/environment state, tool failures/results, intermediate evidence and uncertainty about which action should be taken next. - Decisive decision or feedback right: select substantive tool calls/actions from current evidence and decide whether to continue or conclude the task. - Decision owner: the running model inside Water&#39;s first-party createagentictask loop. - Supporting / enforcement mechanisms: provider adapter, Toolkit/Tool execution, message/tool-call normalization, max-iteration limit, optional done tool, callbacks, stop condition, sandbox/context/memory/resilience capabilities. - Closure path: user/task input → model response/tool choice → Water executes selected tool → observation appended as tool message → next model decision → repeated action or terminal response. - Boundary reachability: createagentictask is exported from the installed water.agents package and documented in the top-level README as the first-party Agentic Loop; subordinate agent tools instantiate the same loop directly. - Why this is / is not agent-owned: Water&#39;s deterministic runtime transports and bounds actions, while the model chooses the operational action from current observations in the ordinary path. Optional callbacks may override individual calls but do not remove the available autonomous mode. - Evidence: water/agents/react.py, README.md, water/agents/subagent.py. - Basis: explicit + structural. - Confidence: high. - Caveats: external model providers supply inference but do not own Water&#39;s first-party loop mechanics. Generic createagenttask one-shot LLM tasks are not the S1 basis; the explicit ReAct implementation is.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no sufficiently evidenced S2-specific attenuation of concrete interference/conflict/oscillation among distinct Water S1 units is established in the reviewed standard distribution. - Disturbance / variety regulated: no specific inter-S1 disturbance satisfying the Profile witness is established. - Decisive decision or feedback right: none established for an S2-specific attenuation relation. - Decision owner: none established for S2. - Supporting / enforcement mechanisms: SharedContext state/message bus, deterministic sequential/round-robin execution, dynamic handoff, subagent isolation, DAG/parallel flow primitives and delegation permissions. - Closure path: no qualifying inter-S1 disturbance → attenuation decision/relation → returned change in subsequent S1 behaviour loop is established. - Why this is / is not agent-owned: Water supplies substantial communication, isolation, sequencing and routing machinery, but the Methodology does not treat those generic primitives as S2 without evidence of an actual/structurally evidenced interference and a relation specifically attenuating it. - Evidence: water/agents/multi.py, tests/testmultiagent.py, water/agents/subagent.py. - Basis: explicit absence after function-first review. - Confidence: high. - Caveats: a downstream Water application could define a real S2 disturbance and use these mechanisms to regulate it; that would be a separate system-in-focus and does not upgrade the repository-level assessment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: - State: C - Function: expose a whole-team current-control path that can choose which operational role receives the next commitment from current team state/history. - Disturbance / variety regulated: changing team state, accumulated role outputs/messages/history and the need to choose or stop the next active role within current work. - Decisive decision or feedback right: emit nextagent from the currently executing team role, thereby selecting the next S1 commitment or ending the dynamic chain; Water validates the requested target and delegation authority. - Decision owner: constructor path. Water exposes the S3-specific whole-team state/transition interface, but application/developer-composed task logic owns the decisive choice in the shipped examples/tests; an autonomous controller must still be composed to receive A. - Supporting / enforcement mechanisms: SharedContext state/messages/history, injection of sharedcontext and agentmessages, team registry, candelegateto, max-round limit and deterministic transition validation. - Closure path: whole-team SharedContext snapshot → current role/task decision emits nextagent → Water validates role and delegation permission → selected role runs next with updated current state/history → later team operation changes. - Boundary reachability: AgentOrchestrator(strategy=&#39;dynamic&#39;), SharedContext injection and nextagent handling are shipped package APIs with direct tests and cookbook usage; no custom Water runtime implementation is needed, only composition of the decisive autonomous actor/logic. - Why this is / is not agent-owned: the first-party primitive is function-specific, but Water&#39;s own supported examples/tests use ordinary Python functions to choose nextagent. Therefore the current-control function is exposed but autonomous ownership is not closed by the repository standard distribution. - Evidence: water/agents/multi.py, tests/testmultiagent.py, cookbook/agents/multiagentflow.py. - Basis: explicit + structural. - Confidence: medium. - Caveats: nextagent alone would be ordinary routing; the S3 constructor claim additionally relies on Water injecting the whole team&#39;s state/messages/history into the role and using the returned decision to alter current team commitments. There is no shipped autonomous controller tied to this interface, so A is not claimed. Approval gates, rate limits and schedulers are enforcement mechanisms and are not counted as S3 ownership. - Whole-system current view: every role task receives a serialized SharedContext containing current shared state, all messages and execution history, plus messages addressed to that role. - Current-control decision scope: choose the next team member to operate (within delegation constraints) or terminate the dynamic handoff chain, changing the team&#39;s current allocation of work.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no live, sufficiently independent complementary audit path is established that returns an audit judgment into subsequent Water operation. - Disturbance / variety regulated: potential hidden divergence between ordinary production reports/outputs and operational reality is not covered by a qualifying first-party audit loop. - Decisive decision or feedback right: none established for independent audit judgment with production feedback closure. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: deterministic/LLM evaluators, guardrails, RetryWithFeedback, observability/traces and ordinary reviewer tasks can inspect outputs, but their roles/closure do not establish S3 at the reviewed boundary. - Closure path: no qualifying complementary evidence → independent audit verdict → corrective return into live/subsequent operation loop is established. - Why this is / is not agent-owned: LLMJudge is an agentic evaluator, but it runs after a completed flow.run against expected output and writes EvalScore/report state rather than steering the production run. RetryWithFeedback closes configured guardrail failures into retries, but the judgment comes from application-supplied checkfn/guardrail rules rather than a separately evidenced independent audit actor. - Evidence: water/eval/evaluators.py, water/eval/suite.py, water/guardrails/retry.py. - Basis: explicit absence after function-first review. - Confidence: high. - Caveats: applications may wire evaluation/reviewer outputs back into a later flow, but that closure is not supplied as a standard first-party audit mode here.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no prospective environment-facing adaptation loop is established that develops options and changes Water&#39;s future operating capability. - Disturbance / variety regulated: no first-party path is established for future-relevant environmental change requiring adaptation of the harness&#39;s capabilities/organization. - Decisive decision or feedback right: none established for choosing and incorporating a future capability adaptation. - Decision owner: none established for S4. - Supporting / enforcement mechanisms: PlannerAgent, persistent layered memory including AUTOLEARNED, eval reports, plugin/configuration surfaces, versioning and ordinary user/developer composition can alter what later runs know or execute. - Closure path: no qualifying external/prospective distinction → adaptation options → selected option → change to present capability/S3 loop is established. - Why this is / is not agent-owned: model planning decomposes the current goal; memory tools store/retrieve notes; evals measure outputs. None of these inspected paths autonomously translates future/environmental intelligence into a changed Water capability or organizational design. - Evidence: water/agents/planner.py, water/agents/memory.py, water/eval/suite.py. - Basis: explicit absence after function-first review. - Confidence: high. - Caveats: AUTOLEARNED is a storage layer name, not evidence of a prospective adaptation function; downstream code can use memories/evals to redesign a harness, but that is external composition.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no runtime identity or ultimate-policy authority loop is established at the reviewed Water harness/team boundary. - Disturbance / variety regulated: no identity/ultimate-policy dispute requiring authoritative organizational closure is evidenced. - Decisive decision or feedback right: none established for S5-level identity or ultimate policy. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: developer system prompts, guardrails, risk/approval policies, ORG-priority memory, tool permissions, delegation constraints, rate/budget limits and human approve/deny actions constrain ordinary operation. - Closure path: no qualifying identity/ultimate-policy matter → authoritative S5 decision → returned governance of subsequent operation loop is established. - Why this is / is not agent-owned: Water&#39;s policy-like mechanisms enforce authored operating constraints or local action approvals. Neither a prompt nor a human approval of a risky task becomes S5 without evidence that it closes identity/ultimate-policy authority at this recursion. - Evidence: water/agents/approval.py, water/agents/memory.py, README.md. - Basis: explicit absence after function-first review. - Confidence: high. - Caveats: operators can impose strong policy and humans can have final say over individual actions, but generic configuration/approval is not the Methodology&#39;s S5 parent-governance case.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/d835ff58ab27a2655c158769c1ae1bb416ebac5b/assessments/water.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit d835ff58ab27a2655c158769c1ae1bb416ebac5b\">d835ff5 &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"2\" data-assessment-at=\"2026-09-17T22:55:55+03:00\"><th scope=\"row\"><a href=\"https://github.com/ruvnet/ruflo\" target=\"_blank\" rel=\"noopener\">Ruflo</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-17\">2026-09-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/ruvnet/ruflo/tree/2602b642d92234c710ffbe96bfb33007d481ceab\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 2602b642d92234c710ffbe96bfb33007d481ceab\">2602b64 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: A. In the documented Codex mode, autonomous Codex workers perform the operational coding/tool-execution loop while Ruflo supplies the surrounding orchestration. This is a supported standard-distribution path rather than a developer-only constructor hook.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: C. Ruflo supplies a concrete inter-worker coordination membrane beyond generic messaging: dependency ordering, isolated writer worktrees, designated ownership of shared integration files, topology/consensus primitives, and failure/recovery routing constrain concurrent-worker interference. The decisive organizational coordination policy remains a constructor/configuration surface rather than a demonstrated autonomous S2 actor, so the path is composable rather than A.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: C. The unified coordinator maintains current swarm state and exposes assignment/reassignment, health/recovery, topology, concurrency/budget and policy-envelope controls over the whole active swarm. These are genuine current-regulation decision rights, but the reviewed standard path does not establish an autonomous agent as the owner of those whole-system decisions.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: —. Validation, consensus, security and monitoring paths were not shown to provide materially independent access to operational reality with complementary corrective closure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: —. The learning bridge consolidates internal trajectories, rewards, confidence and memory. That is retrospective self-improvement inside the operating history, not evidence of an outside-looking prospective intelligence loop that adapts the organization to a changing external environment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: —. Deterministic policy rules, approval gates and deployment configuration constrain operation but do not establish a first-party identity/ultimate-policy tension-and-resolution loop.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9b431dfc4e818567d073e9a545bf346497b4addd/assessments/ruflo.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9b431dfc4e818567d073e9a545bf346497b4addd\">9b431df &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:15:49+03:00\"><th scope=\"row\"><a href=\"https://github.com/openai/openai-agents-js\" target=\"_blank\" rel=\"noopener\">OpenAI Agents SDK for JavaScript</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/openai/openai-agents-js/tree/8831eae9d34365f9a397cbd52ae0366f304e1a96\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 8831eae9d34365f9a397cbd52ae0366f304e1a96\">8831eae &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: agents autonomously choose tools/actions and execute text/voice tasks within configured run boundaries.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: handoffs transfer control and agents-as-tools delegate work; neither mechanism by itself regulates interference, oscillation or shared constraints among multiple autonomous S1 units. The shallow S2=C interpretation is removed.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: manager-style composition remains task orchestration and does not establish whole-system authority over shared resources/capacity/commitments.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: evaluator/guardrail patterns require application-defined placement and authority and, in the reviewed SDK boundary, are normal validation/composition rather than a supplied complementary audit channel. The shallow S3=C interpretation is removed.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: routing, session state and current-run orchestration do not provide a distinct prospective environment-intelligence function.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: instructions, guardrails, handoff topology and application policy remain developer-owned.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/0b75c7fb0539831a89e5ca33f4cf1df430f3550f/assessments/openai-agents-js.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 0b75c7fb0539831a89e5ca33f4cf1df430f3550f\">0b75c7f &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"0\" data-assessment-at=\"2026-09-17T20:13:36+03:00\"><th scope=\"row\"><a href=\"https://github.com/charmbracelet/crush\" target=\"_blank\" rel=\"noopener\">Crush</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-17\">2026-09-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/charmbracelet/crush/tree/ef7bae117905a3927b177ed6923f36e811737d53\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision ef7bae117905a3927b177ed6923f36e811737d53\">ef7bae1 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: the primary coding agent autonomously selects tools/actions and iterates from repository/tool feedback.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: parallel task-agent fan-out is delegation. No specific inter-S1 interference, oscillation or conflict plus a first-party attenuation/feedback relation was established. Serialized permission prompts concern tool authorization, not mutual adjustment among autonomous S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: the permission service grants or denies individual tool actions and the coordinator runs delegated agents, but no whole-system current view plus organizational authority over shared resources, commitments, priorities or accountability was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: hooks and permission checks sit in the normal execution/authorization path; no sufficiently independent complementary audit channel with alternative access to operational reality was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: no prospective environment-facing adaptation loop was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: grant/deny decisions are operational tool permissions. They do not establish identity or ultimate-policy closure, so ordinary human permission prompts are not published as S5=P.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/3c76cda1b3c51a33c84eeaa45ac3c296a54f8c3c/assessments/crush.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 3c76cda1b3c51a33c84eeaa45ac3c296a54f8c3c\">3c76cda &#8599;</a></td></tr>","<tr data-a=\"1\" data-c=\"1\" data-assessment-at=\"2026-09-17T01:36:15+03:00\"><th scope=\"row\"><a href=\"https://github.com/strands-agents/harness-sdk\" target=\"_blank\" rel=\"noopener\">Strands Agents</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"1\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>1</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/strands-agents/harness-sdk/tree/08ed4cfd3eb42ae9f668595e675d5f196eee7e44\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 08ed4cfd3eb42ae9f668595e675d5f196eee7e44\">08ed4cf &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a\" title=\"S1 / operation: individual agents autonomously select tools/actions and produce operational results.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: first-party Swarm primitives provide peer transfers plus a configurable mechanism specifically aimed at repetitive-handoff/oscillation control. This is more than delegation or static graph routing, but the developer must configure/close the regulation policy, so the function is composable rather than out-of-box agent-owned.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: swarm runtime state and transfer selection do not establish a whole-system authority that regulates shared resources, capacity, priorities and commitments across S1 units.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: no independent complementary audit channel distinct from normal swarm execution was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: dynamic handoff selection responds to current task state, not a prospective environment-intelligence function adapting future system capability.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: swarm membership, thresholds, prompts, tools and policy are developer/application supplied.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/7da944be89535df1cb7917ad2d2fc20081578e30/assessments/strands-agents.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 7da944be89535df1cb7917ad2d2fc20081578e30\">7da944b &#8599;</a></td></tr>"];
